package com.trawlingplus;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TrawlingPlusPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TrawlingPlusPlugin.class);
		RuneLite.main(args);
	}
}

package com.trawlingplus;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ShoalRouteTest
{
	// A 10 by 10 square swum from the origin, 40 tiles round, with stops at 10 and 30 tiles.
	private static final ShoalRoute SQUARE = new ShoalRoute("Test", "Square", 0,
		new double[][]{{0, 0}, {10, 0}, {10, 10}, {0, 10}},
		new double[][]{{10, 0}, {0, 10}}, null, null);

	@Test
	public void projectsOntoTheNearestPointOfTheLoop()
	{
		ShoalRoute.Projection onPath = SQUARE.project(5, 0);
		assertEquals(5, onPath.distance, 1e-9);
		assertEquals(0, onPath.offset, 1e-9);

		ShoalRoute.Projection offPath = SQUARE.project(5, -2);
		assertEquals(5, offPath.distance, 1e-9);
		assertEquals(2, offPath.offset, 1e-9);

		// The closing edge, from the last point back to the first.
		assertEquals(35, SQUARE.project(0, 5).distance, 1e-9);
	}

	@Test
	public void followingAlongALongStraightNeverJumpsAhead()
	{
		// Sides far longer than the stretch of route a shoal is followed within.
		ShoalRoute big = new ShoalRoute("Test", "Big", 0,
			new double[][]{{0, 0}, {40, 0}, {40, 40}, {0, 40}},
			new double[][]{{40, 0}}, null, null);
		double distance = big.project(0, 0).distance;
		for (double x = 0.5; x < 40; x += 0.5)
		{
			distance = big.project(x, 0, distance).distance;
			assertEquals("following at x = " + x, x, distance, 1e-9);
		}
	}

	@Test
	public void nextStopIsTheFirstOneAhead()
	{
		assertEquals(0, SQUARE.nextStop(5));
		assertEquals(1, SQUARE.nextStop(15));
	}

	@Test
	public void nextStopWrapsRoundTheLoop()
	{
		assertEquals(0, SQUARE.nextStop(35));
	}

	@Test
	public void aShoalSittingAtAStopIsHeadingForTheOneAfter()
	{
		assertEquals(1, SQUARE.nextStop(10));
		assertEquals(1, SQUARE.nextStop(8.5));
		assertEquals(0, SQUARE.nextStop(29));
	}

	@Test
	public void piecesShorterThanTheSpacingAreNotSplit()
	{
		ShoalRoute small = new ShoalRoute("Test", "Small", 0,
			new double[][]{{0, 0}, {2, 0}, {2, 2}, {0, 2}},
			new double[][]{{2, 0}}, null, null);
		assertEquals(4, small.sampleCount());
	}

	@Test
	public void samplesCoverTheLoopInOrder()
	{
		// Each 10 tile side is a straight, split into four pieces no longer than 3 tiles.
		assertEquals(16, SQUARE.sampleCount());
		assertEquals(0, SQUARE.sampleAt(0));
		assertEquals(4, SQUARE.sampleAt(10));
		// Past the last sample wraps back round to the first.
		assertEquals(0, SQUARE.sampleAt(39.5));
	}

	@Test
	public void pointAtFollowsTheRouteAndTheWayItRuns()
	{
		assertPoint(SQUARE.pointAt(5), 5, 0, 1, 0);
		assertPoint(SQUARE.pointAt(12.5), 10, 2.5, 0, 1);
		// On the closing edge, heading back to the start.
		assertPoint(SQUARE.pointAt(39.5), 0, 0.5, 0, -1);
		// Distances past the end wrap round.
		assertPoint(SQUARE.pointAt(45), 5, 0, 1, 0);
	}

	@Test
	public void overlapsOnlyRectanglesItReachesInto()
	{
		assertTrue(SQUARE.overlaps(5, 5, 20, 20));
		// Touching a corner counts.
		assertTrue(SQUARE.overlaps(-5, -5, 0, 0));
		assertFalse(SQUARE.overlaps(11, 11, 30, 30));
	}

	@Test
	public void lightSmoothingPassesThroughEveryPoint()
	{
		double[][] points = {{0, 0}, {10, 0}, {10, 10}, {0, 10}};
		double[][] curve = ShoalRoute.catmullRom(points);
		for (double[] point : points)
		{
			boolean found = false;
			for (double[] c : curve)
			{
				found |= Math.abs(c[0] - point[0]) < 1e-9 && Math.abs(c[1] - point[1]) < 1e-9;
			}
			assertTrue("curve misses " + point[0] + ", " + point[1], found);
		}
	}

	@Test
	public void heavySmoothingRunsThroughEveryStop()
	{
		// Heavy smoothing would cut these corners by over a tile, so stops on two of them have to be pulled onto.
		double[][] points = {{0, 0}, {20, 0}, {20, 20}, {0, 20}};
		double[][] stops = {{20, 0}, {0, 20}};
		ShoalRoute route = new ShoalRoute("Test", "Corners", 0, ShoalRoute.bSpline(points, stops), stops, null, null);
		for (int stop = 0; stop < route.stopCount(); stop++)
		{
			assertEquals(0, route.project(route.stopX(stop), route.stopY(stop)).offset, 0.01);
		}
	}

	@Test
	public void smoothingKeepsStraightStretchesStraight()
	{
		// Between (10, 0) and (20, 0) the neighbouring points are in line too, so neither curve can bend.
		double[][] points = {{0, 0}, {10, 0}, {20, 0}, {30, 0}, {30, 10}, {0, 10}};
		for (double[][] curve : new double[][][]{ShoalRoute.catmullRom(points), ShoalRoute.bSpline(points, new double[0][])})
		{
			for (double[] c : curve)
			{
				if (c[0] >= 10 && c[0] <= 20 && c[1] < 5)
				{
					assertEquals(0, c[1], 1e-9);
				}
			}
		}
	}

	@Test
	// Two tiles leaves room under the 3 a shoal may stray from its route before it stops being matched.
	public void smoothingNeverPullsARouteMoreThanTwoTilesOffItsPath() throws IOException
	{
		RouteData data = ShoalRoute.read(new Gson());
		for (RouteData.Species species : data.species)
		{
			for (RouteData.Route route : species.routes)
			{
				ShoalRoute original = new ShoalRoute(species.name, route.name, route.stopTicks,
					route.path, route.stops, route.safe, route.threats);
				for (double[][] curve : new double[][][]{ShoalRoute.catmullRom(route.path), ShoalRoute.bSpline(route.path, route.stops)})
				{
					for (double[] point : curve)
					{
						double offset = original.project(point[0], point[1]).offset;
						assertTrue(route.name + " curve is " + offset + " tiles off its path", offset <= 2);
					}
				}
			}
		}
	}

	@Test
	public void buildsEveryRouteWithItsStopsOnThePath() throws IOException
	{
		RouteData data = ShoalRoute.read(new Gson());
		for (TrawlingPlusConfig.Smoothing smoothing : TrawlingPlusConfig.Smoothing.values())
		{
			List<ShoalRoute> routes = ShoalRoute.build(data, smoothing);
			assertFalse(routes.isEmpty());
			for (int index = 0; index < routes.size(); index++)
			{
				ShoalRoute route = routes.get(index);
				for (int stop = 0; stop < route.stopCount(); stop++)
				{
					double offset = route.project(route.stopX(stop), route.stopY(stop)).offset;
					assertTrue(smoothing + " " + route.getSpecies() + " route " + index + " stop " + stop + " is " + offset + " tiles off its path", offset <= 1);
				}
			}
		}
	}

	private static void assertPoint(double[] point, double x, double y, double dx, double dy)
	{
		assertEquals(x, point[0], 1e-9);
		assertEquals(y, point[1], 1e-9);
		assertEquals(dx, point[2], 1e-9);
		assertEquals(dy, point[3], 1e-9);
	}
}

package com.trawlingplus;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ShoalTest
{
	@Test
	public void headingArrowShowsTheTickTheShoalMovesOff()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);
		for (int tick = 0; tick < 70; tick++)
		{
			shoal.update(new double[]{2, 0}, null);
		}
		assertEquals(0, shoal.headingArrowOpacity(0), 1e-9);
		assertEquals(0, shoal.headingArrowOpacity(600), 1e-9);

		shoal.update(new double[]{4, 0}, null);
		assertEquals(1, shoal.headingArrowOpacity(1200), 1e-9);
	}

	@Test
	public void headingArrowStaysHiddenForAShoalFirstSeenSittingStill()
	{
		Shoal shoal = new Shoal(null);
		for (int tick = 0; tick < 200; tick++)
		{
			shoal.update(new double[]{5, 5}, null);
			assertEquals("opacity on tick " + tick, 0, shoal.headingArrowOpacity(tick * 600L), 1e-9);
		}

		// Until it swims off.
		shoal.update(new double[]{7, 5}, null);
		assertEquals(1, shoal.headingArrowOpacity(200 * 600L), 1e-9);
	}

	@Test
	public void headingArrowFadesInOverATick()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);

		// It starts invisible; the first frame just starts the clock.
		assertEquals(0, shoal.headingArrowOpacity(1000), 1e-9);
		assertEquals(0.5, shoal.headingArrowOpacity(1300), 1e-9);
		assertEquals(1, shoal.headingArrowOpacity(1600), 1e-9);
		assertEquals(1, shoal.headingArrowOpacity(5000), 1e-9);
	}

	@Test
	public void stoppedTheTickTheDestinationStopsChanging()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, new double[]{1, 0});
		shoal.update(new double[]{0.5, 0}, new double[]{2, 0});
		assertFalse(shoal.stopped());

		// Still gliding towards its last destination, but no new one was sent, so it has stopped.
		shoal.update(new double[]{1.5, 0}, new double[]{2, 0});
		assertTrue(shoal.stopped());

		// A new destination means it has set off, before it has visibly moved.
		shoal.update(new double[]{2, 0}, new double[]{3, 0});
		assertFalse(shoal.stopped());
	}

	@Test
	public void headingArrowFadesOutWhenTheShoalStops()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);
		shoal.headingArrowOpacity(0);
		assertEquals(1, shoal.headingArrowOpacity(600), 1e-9);

		// Sits still on the next tick, so the arrow fades away.
		shoal.update(new double[]{2, 0}, null);
		assertEquals(0.5, shoal.headingArrowOpacity(900), 1e-9);
		assertEquals(0, shoal.headingArrowOpacity(1200), 1e-9);
	}

	@Test
	public void routeDrawsOutToANewNextStopOverTheAnimationDuration()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(0, shoal.routeReveal(1000, 7000), 1e-9);
		// Waits half a second for the shoal to settle in first.
		assertFalse(shoal.revealStarted(1400));
		assertTrue(shoal.revealStarted(1500));
		assertEquals(0, shoal.routeReveal(1500, 7000), 1e-9);
		assertEquals(0.28 / 3, shoal.routeReveal(2900, 7000), 1e-9);
		assertEquals(11.0 / 24, shoal.routeReveal(5000, 7000), 1e-9);
		assertEquals(1, shoal.routeReveal(8500, 7000), 1e-9);
		assertEquals(1, shoal.routeReveal(11000, 7000), 1e-9);

		// A shorter animation gets there sooner.
		assertEquals(11.0 / 24, shoal.routeReveal(3000, 3000), 1e-9);
		assertEquals(1, shoal.routeReveal(4500, 3000), 1e-9);
	}

	@Test
	public void nextStopFadesInOnceTheRouteReachesIt()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(0, shoal.nextStopReveal(4500, 7000), 1e-9);
		assertEquals(0, shoal.nextStopReveal(8500, 7000), 1e-9);
		assertEquals(0.5, shoal.nextStopReveal(8650, 7000), 1e-9);
		assertEquals(1, shoal.nextStopReveal(8800, 7000), 1e-9);
	}

	@Test
	public void remembersTheStopJustReachedUntilCleared()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(-1, shoal.arrivedStop());

		shoal.headFor(3, 2000);
		assertEquals(2, shoal.arrivedStop());

		shoal.clearArrivedStop();
		assertEquals(-1, shoal.arrivedStop());
	}

	@Test
	public void revealOnlyRestartsWhenTheNextStopChanges()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		shoal.headFor(2, 7800);
		assertEquals(1, shoal.routeReveal(8500, 7000), 1e-9);

		shoal.headFor(3, 9000);
		assertEquals(0, shoal.routeReveal(9000, 7000), 1e-9);
		assertEquals(0, shoal.nextStopReveal(9000, 7000), 1e-9);
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Marks up the facilities tab of the sailing side panel: how deep each trawling net is set, and which
 * button moves it towards the depth of the nearest shoal.
 */
class TrawlingPlusNetOverlay extends Overlay
{
	// A row is a trawling net if its picture is one of these four, which are the net raised, then at
	// each of the three fishing depths. The panel only gives the raise and lower buttons an action
	// while someone, the player or a crewmate, is operating that net, so the picture is what the marks
	// hang off. It has to be the picture itself: the frames and arrows beside it are shared with every
	// other kind of row.
	private static final int NET_PICTURE_RAISED = SpriteID.IconSailingFacilities24x24._12;
	private static final int NET_PICTURE_DEEPEST = SpriteID.IconSailingFacilities24x24._15;

	private static final String LOWER = "Lower net";
	private static final String RAISE = "Raise net";

	// The letter for each of the four net pictures, in the same order: raised, then the three fishing depths.
	private static final String[] LETTERS = {"R", "S", "M", "D"};
	private static final Color RAISED_COLOUR = Color.WHITE;

	private static final Color HIGHLIGHT = new Color(255, 200, 0);
	private static final Color PILL = new Color(0, 0, 0, 170);
	static final Color TICK = new Color(0, 220, 80);
	private static final int PILL_PADDING = 3;

	// The tick is drawn by hand, so its size is known rather than measured.
	static final int TICK_WIDTH = 9;

	// A button counts as being on a row if their middles are within this many pixels.
	private static final int SAME_ROW = 16;

	// Pictures of facilities sit in a column down the left of the panel; the buttons start well right
	// of it. Without this the marks latch onto button frames and arrows as well.
	private static final int PICTURE_COLUMN = 40;

	// The last depth and place each net was seen with, by its position among the rows. While a net is
	// being raised or lowered its picture briefly is not one of the four depth pictures, and drawing from
	// what was last seen keeps the marks from flickering off for those frames.
	private final Map<Integer, NetRow> lastSeen = new HashMap<>();

	// The last button highlighted on each net, by the same position, and when it was last found. Between
	// the steps of a net being raised or lowered its button briefly loses its action, which looks the same
	// as nobody operating the net, so the highlight is held for up to a game tick rather than dropped.
	private final Map<Integer, SeenButton> lastButtons = new HashMap<>();
	private static final long BUTTON_GRACE_MILLIS = 600;

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;

	@Inject
	TrawlingPlusNetOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Each piece of the panel stands on its own; with all three off there is nothing to draw, and
		// neither is there on a boat with no trawling net to mark up.
		boolean anything = plugin.showGuides()
			&& (config.showNetDepths() || config.showNetButton() || config.showNetCorrect());
		Widget rows = anything
			? client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_ROWS)
			: null;
		if (rows == null || rows.isHidden())
		{
			return null;
		}

		// Rows scroll inside a window, and one scrolled past its edge still reports a place on screen.
		// Clipping to the window keeps the marks off whatever is drawn beyond it, and cuts a part
		// scrolled row the same way the panel cuts the row itself.
		Widget window = client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_SCROLLABLE);
		Shape clip = graphics.getClip();
		if (window != null && !window.isHidden())
		{
			graphics.clip(window.getBounds());
		}

		// The buttons are only wanted for the guide, and only carry an action while someone is operating that net.
		List<Widget> buttons = config.showNetButton() ? netButtons() : Collections.emptyList();
		long now = System.currentTimeMillis();
		int wanted = plugin.getNearestDepth().netDepth();
		for (NetRow net : netRows(rows))
		{
			// The picture of a net is its depth, so a row can never be labelled with another net.
			int depth = net.depth;
			Rectangle picture = net.picture;
			// The two share the picture when both are switched on, and take the middle of it when
			// either has the row to itself.
			boolean withLetter = config.showNetDepths();
			boolean withTick = config.showNetCorrect();
			int middle = picture.y + picture.height / 2;

			if (withLetter)
			{
				int width = pillWidth(graphics, LETTERS[depth]);
				int left = withTick ? picture.x - 3 : picture.x + (picture.width - width) / 2;
				drawPill(graphics, LETTERS[depth], letterColour(depth), left, middle);
			}

			if (wanted < 0)
			{
				// Nothing known to aim at, so no advice either way.
				continue;
			}

			if (depth == wanted)
			{
				if (withTick)
				{
					// Nudged in from the right edge, which sits it evenly against the letter.
					int left = withLetter
						? picture.x + picture.width - TICK_WIDTH - 2
						: picture.x + (picture.width - TICK_WIDTH) / 2;
					drawTick(graphics, left, middle, TICK);
				}
			}
			else if (config.showNetButton())
			{
				// Lowering a net takes it deeper, so the button to press follows the numbers.
				Rectangle press = guideButton(buttons, net, middle, depth < wanted, now);
				if (press != null)
				{
					highlight(graphics, press);
				}
			}
		}

		graphics.setClip(clip);
		return null;
	}

	/**
	 * The trawling nets on the panel with their depths, top row first. A depth is only ever read off one
	 * of the four depth pictures; for the moments a net's picture is anything else, it is drawn as it was
	 * last seen.
	 */
	private List<NetRow> netRows(Widget rows)
	{
		List<NetRow> nets = new ArrayList<>();
		for (Widget child : children(rows))
		{
			if (child == null || child.getRelativeX() >= PICTURE_COLUMN)
			{
				continue;
			}

			int sprite = child.getSpriteId();
			boolean net = sprite >= NET_PICTURE_RAISED && sprite <= NET_PICTURE_DEEPEST;
			Rectangle bounds = child.getBounds();
			// Some frames hand back a picture the panel has not laid out yet.
			if (net && !child.isHidden() && bounds.y >= 0 && bounds.height > 0)
			{
				NetRow row = new NetRow(child.getIndex(), sprite - NET_PICTURE_RAISED, bounds);
				lastSeen.put(child.getIndex(), row);
				nets.add(row);
			}
			else if (sprite > 0 && !net)
			{
				// The picture of something else entirely, so whatever net was in this place has gone.
				lastSeen.remove(child.getIndex());
			}
			else
			{
				NetRow seen = lastSeen.get(child.getIndex());
				if (seen != null)
				{
					nets.add(seen);
				}
			}
		}

		nets.sort((one, other) -> Integer.compare(one.picture.y, other.picture.y));
		return nets;
	}

	/**
	 * Every raise or lower button the panel is currently offering. They only carry an action while someone
	 * is operating that net, so there may be none at all.
	 */
	private List<Widget> netButtons()
	{
		List<Widget> buttons = new ArrayList<>();
		Widget clicks = client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_CONTENT_CLICKLAYER);
		if (clicks == null || clicks.isHidden())
		{
			return buttons;
		}

		for (Widget child : children(clicks))
		{
			if (child != null && !child.isHidden() && buttonKind(child) >= 0)
			{
				buttons.add(child);
			}
		}
		return buttons;
	}

	/**
	 * Where the button that moves a net the given way is, or where it last was if it went missing less
	 * than a game tick ago, or null.
	 */
	private Rectangle guideButton(List<Widget> buttons, NetRow net, int middle, boolean lowering, long now)
	{
		Widget press = buttonOnRow(buttons, middle, lowering);
		if (press != null)
		{
			Rectangle bounds = press.getBounds();
			lastButtons.put(net.index, new SeenButton(bounds, lowering, now));
			return bounds;
		}

		SeenButton seen = lastButtons.get(net.index);
		return seen != null && seen.lowering == lowering && now - seen.millis <= BUTTON_GRACE_MILLIS
			? seen.bounds
			: null;
	}

	private static Widget buttonOnRow(List<Widget> buttons, int middle, boolean lowering)
	{
		for (Widget button : buttons)
		{
			Rectangle bounds = button.getBounds();
			boolean lowers = buttonKind(button) == 0;
			if (lowers == lowering && Math.abs(bounds.y + bounds.height / 2 - middle) <= SAME_ROW)
			{
				return button;
			}
		}
		return null;
	}

	private static Widget[] children(Widget widget)
	{
		Widget[] children = widget.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			children = widget.getChildren();
		}
		return children == null ? new Widget[0] : children;
	}

	/**
	 * 0 for the button that lowers a net, 1 for the one that raises it, and -1 for anything else.
	 */
	private static int buttonKind(Widget widget)
	{
		String[] actions = widget.getActions();
		for (String action : actions == null ? new String[0] : actions)
		{
			if (LOWER.equals(action))
			{
				return 0;
			}
			if (RAISE.equals(action))
			{
				return 1;
			}
		}
		return -1;
	}

	/**
	 * A colour with any transparency taken out. Text is always drawn solid, whatever a saved colour
	 * says, since see-through lettering is only ever harder to read.
	 */
	static Color opaque(Color colour)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	private Color letterColour(int depth)
	{
		switch (depth)
		{
			case 1:
				return opaque(config.shallowDepthColour());
			case 2:
				return opaque(config.moderateDepthColour());
			case 3:
				return opaque(config.deepDepthColour());
			default:
				return RAISED_COLOUR;
		}
	}

	/**
	 * A letter on a dark pill, starting at the given edge and centred on the given line.
	 */
	private static void drawPill(Graphics2D graphics, String letter, Color colour, int left, int middle)
	{
		FontMetrics letters = graphics.getFontMetrics();
		int width = letters.stringWidth(letter) + PILL_PADDING * 2;
		int height = letters.getAscent() + PILL_PADDING * 2;
		int top = middle - height / 2;

		graphics.setColor(PILL);
		graphics.fillRoundRect(left, top, width, height, 6, 6);
		graphics.setColor(colour);
		graphics.drawString(letter, left + PILL_PADDING, top + height - PILL_PADDING);
	}

	/**
	 * A tick starting at the given edge and centred on the given line. Shared with the display at the
	 * helm, which ticks the depth once every net is set to it.
	 */
	static void drawTick(Graphics2D graphics, int left, int middle, Color colour)
	{
		graphics.setColor(colour);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawLine(left, middle, left + 3, middle + 4);
		graphics.drawLine(left + 3, middle + 4, left + TICK_WIDTH, middle - 5);
	}

	private static int pillWidth(Graphics2D graphics, String text)
	{
		return graphics.getFontMetrics().stringWidth(text) + PILL_PADDING * 2;
	}

	private static void highlight(Graphics2D graphics, Rectangle button)
	{
		graphics.setColor(new Color(HIGHLIGHT.getRed(), HIGHLIGHT.getGreen(), HIGHLIGHT.getBlue(), 110));
		graphics.fillRoundRect(button.x, button.y, button.width, button.height, 6, 6);
		graphics.setColor(new Color(HIGHLIGHT.getRed(), HIGHLIGHT.getGreen(), HIGHLIGHT.getBlue(), 220));
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRoundRect(button.x, button.y, button.width - 1, button.height - 1, 6, 6);
	}

	/**
	 * A trawling net on the panel: how deep it is set, and where its picture is.
	 */
	private static final class NetRow
	{
		final int index;
		final int depth;
		final Rectangle picture;

		NetRow(int index, int depth, Rectangle picture)
		{
			this.index = index;
			this.depth = depth;
			this.picture = picture;
		}
	}

	/**
	 * A button highlighted on a net: where it was, which way it moves the net, and when it was last found.
	 */
	private static final class SeenButton
	{
		final Rectangle bounds;
		final boolean lowering;
		final long millis;

		SeenButton(Rectangle bounds, boolean lowering, long millis)
		{
			this.bounds = bounds;
			this.lowering = lowering;
			this.millis = millis;
		}
	}
}

package com.trawlingplus;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the nearest shoal route on the minimap. Separate from the world map because the two are drawn
 * at different sizes, from different sets of routes, and the minimap leaves out the direction arrows:
 * at its size they cost more to place than they are worth.
 */
class TrawlingPlusMinimapOverlay extends Overlay
{
	// The minimap sits in a different place in each of the three screen layouts.
	private static final int[] MINIMAPS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP
	};

	private static final int THICKNESS = 1;
	private static final int SHOAL = 3;

	// What the minimap draws a tile as, if it cannot be measured. It usually can.
	private static final double PIXELS_PER_TILE = 4;

	// How far apart the two points used to measure the minimap's scale are, in tiles, and how much
	// slack to leave around what it can show: the minimap is centred on the player rather than on the
	// boat, and a boat is ten tiles long.
	private static final int SCALE_TILES = 16;
	private static final double EDGE_SLACK = 8;

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;

	@Inject
	TrawlingPlusMinimapOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Behind Show guides, and so behind being on a boat at all, unlike the world map: the minimap is
		// for steering by, which is done from a boat.
		TrawlingPlusConfig.ShowOnMaps where = config.showOnMaps();
		if (client.getGameState() != GameState.LOGGED_IN
			|| !plugin.showGuides()
			|| where == TrawlingPlusConfig.ShowOnMaps.OFF
			|| where == TrawlingPlusConfig.ShowOnMaps.WORLD_MAP)
		{
			return null;
		}

		WorldView view = client.getTopLevelWorldView();
		Widget minimap = minimap();
		if (view == null || minimap == null)
		{
			return null;
		}

		// The map is round inside a square widget, so a line has to be kept out of the corners, which are
		// well outside the map. Each point is dropped by hand rather than by clipping the drawing to a
		// circle: a clip that is not a rectangle takes Java2D off its quick path, and it is charged for
		// on everything drawn afterwards. The frame laps over the edge of the circle in places and a line
		// can still meet it there, which is better than the alternatives: drawing under the interface
		// hides the line behind the map, and pulling the circle in far enough to clear the frame leaves a
		// ring of map nothing is ever drawn on.
		Rectangle bounds = minimap.getBounds();
		double middleX = bounds.x + bounds.width / 2.0;
		double middleY = bounds.y + bounds.height / 2.0;
		double radius = Math.min(bounds.width, bounds.height) / 2.0;
		MapRoutes.Projection onto = (x, y) ->
		{
			Point at = onMinimap(view, x, y);
			return at == null || Math.hypot(at.getX() - middleX, at.getY() - middleY) > radius ? null : at;
		};

		Shape clip = graphics.getClip();
		graphics.clip(bounds);

		// The route the boat is nearest, the same one the water shows, rather than every route that
		// reaches the loaded map. It is drawn whether or not its shoal is in view: a shoal swims out of
		// range long before its route does, and a line that vanishes with the shoal is no use for
		// steering back to it.
		ShoalRoute route = plugin.getNearestRoute();
		double[] boat = plugin.getBoatPlace();

		// How much of a tile the minimap draws, measured off two points a known distance apart beside
		// the boat. They are measured there rather than anywhere else because the minimap will not place
		// a point much more than fifty tiles from the player. Turning with the compass moves the pair
		// but does not change how far apart they end up.
		double acrossX = boat == null ? view.getBaseX() + view.getSizeX() / 2.0 : boat[0];
		double acrossY = boat == null ? view.getBaseY() + view.getSizeY() / 2.0 : boat[1];
		Point middle = onMinimap(view, acrossX, acrossY);
		Point along = onMinimap(view, acrossX + SCALE_TILES, acrossY);
		double measured = middle == null || along == null ? 0
			: Math.hypot(along.getX() - middle.getX(), along.getY() - middle.getY()) / SCALE_TILES;
		double pixelsPerTile = measured > 0 ? measured : PIXELS_PER_TILE;

		// Only the stretch of route the minimap could show, which is a good deal less than the map that
		// is loaded: the minimap holds a couple of dozen tiles where the scene holds a hundred. Without
		// this, most of the route is placed on the minimap only to be found outside its edge and thrown
		// away. With no boat to centre it on, the whole scene is used.
		double reach = radius / pixelsPerTile + EDGE_SLACK;
		double fromX = boat == null ? view.getBaseX() : boat[0] - reach;
		double fromY = boat == null ? view.getBaseY() : boat[1] - reach;
		double toX = boat == null ? view.getBaseX() + view.getSizeX() : boat[0] + reach;
		double toY = boat == null ? view.getBaseY() + view.getSizeY() : boat[1] + reach;

		if (route != null && route.overlaps(fromX, fromY, toX, toY))
		{
			MapRoutes.route(graphics, config, route, onto, THICKNESS, pixelsPerTile, fromX, fromY, toX, toY);
		}

		// Only a shoal the client is drawing in the world may be marked on the map.
		for (Shoal shoal : plugin.getShoals())
		{
			if (shoal.rendered(client))
			{
				MapRoutes.shoal(graphics, config, client, shoal, onto, SHOAL);
			}
		}

		graphics.setClip(clip);
		return null;
	}

	/**
	 * World tile coordinates as a point on the minimap, or null when they are off the loaded map or
	 * too far out for the minimap to hold.
	 */
	private Point onMinimap(WorldView view, double x, double y)
	{
		int localX = (int) Math.round((x - view.getBaseX()) * Perspective.LOCAL_TILE_SIZE)
			+ Perspective.LOCAL_HALF_TILE_SIZE;
		int localY = (int) Math.round((y - view.getBaseY()) * Perspective.LOCAL_TILE_SIZE)
			+ Perspective.LOCAL_HALF_TILE_SIZE;
		if (localX < 0 || localY < 0 || localX >= view.getSizeX() * Perspective.LOCAL_TILE_SIZE
			|| localY >= view.getSizeY() * Perspective.LOCAL_TILE_SIZE)
		{
			return null;
		}

		return Perspective.localToMinimap(client, new LocalPoint(localX, localY, view));
	}

	/**
	 * Whichever screen layout is up, and its minimap, or null if none of them is.
	 */
	private Widget minimap()
	{
		for (int id : MINIMAPS)
		{
			Widget found = client.getWidget(id);
			if (found != null && !found.isHidden())
			{
				return found;
			}
		}
		return null;
	}
}

