		return fishLabel;
	}

	/**
	 * Whether the hold is full: the nets were last emptied into it without room for them all, or it showed
	 * no free slots when last opened, and it has not been seen with room since.
	 */
	boolean isHoldFull()
	{
		return holdFull;
	}

