	 * Whether the boat has a trawling net in either slot, kept up to date as the game changes the slots.
	 */
	boolean netsFitted()
	{
		return netsFitted;
	}

	private boolean readNetsFitted()
	{
		// Each slot names the hotspot its net is built on, so an empty slot names no hotspot.
		return client.getVarbitValue(NET_SLOTS[0]) > 0 || client.getVarbitValue(NET_SLOTS[1]) > 0;
	}

	private boolean readNetsLowered()
	{
		// A net's depth reads 0 while it is raised out of the water, and 1 to 3 at the fishing depths.
		return client.getVarbitValue(NET_DEPTHS[0]) > 0 || client.getVarbitValue(NET_DEPTHS[1]) > 0;
	}

	/**
	 * Keeps count of the fish in the nets from what the game says about them, since nothing else tells.
	 * Every catch, the crew's included, is announced with how many fish it brought in, and emptying the
	 * nets or taking everything from them leaves none.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.MESBOX)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message.startsWith("Your crew start moving the contents of the cargo hold"))
		{
			// Asking the crew on the dock to move everything in the hold to the bank empties it. This is said
			// off the boat, so it comes before the check for being aboard; what the crewmate says once it is
			// done is in their own words, so this is the line to go by.
			holdFull = false;
			return;
		}

		if (boatPlace == null)
		{
			return;
		}

		if (message.startsWith("Your crewmate on the chum station can"))
		{
			// "...can't find any offcuts in the cargo hold." Nothing was laid, and the hold has none of what the
			// nearest shoal takes.
			noBait();
			return;
		}

		if (message.startsWith("There are no fish in"))
		{
			// What opening an empty net says, in a box of its own rather than the menu a net with fish opens.
			noteFish(0);
		}
		else if (message.startsWith("You empty the net"))
		{
			// "..., but there was not enough space in there to do so entirely." A hold without room for them
			// all keeps some back and doesn't say how many; one that took them all had room.
			boolean noRoom = message.contains("not enough");
			if (noRoom && !holdFull)
			{
				notifier.notify(config.notifyHoldFull(), "Your cargo hold is full.");
			}
			holdFull = noRoom;
			if (noRoom)
			{
				setFish(-1);
			}
			else
			{
				noteFish(0);
			}
		}
		else if (message.startsWith("You take all of the fish from the net"))
		{
			noteFish(0);
		}
		else if (message.startsWith("You take some fish from the net"))
		{
			// An inventory without room for them all takes as many as fit, and doesn't say how many. The
			// inventory does, and its update can come either side of this message on the same tick.
			if (inventoryTick == client.getTickCount())
			{
				takeFromNets(inventoryAdded);
			}
			else
			{
				takePending = true;
			}
		}
		else if (message.startsWith("Your net has no more space"))
		{
			// "Your net has no more space for any raw bluefin." The nets hold one catch between them, so this
			// is all of them full.
			warnNetsFull();
		}
		else if (netsFitted())
		{
			// Only with a net fitted: the messages above name the nets, but a catch could be ordinary fishing.
			// A catch whose count can't be read, like "You catch some shrimps" from ordinary fishing, is not a
			// trawling catch and changes nothing. "Trawler's trust: You catch an additional fish." doesn't
			// match either, which is right: that fish is already in the number of the catch line after it.
			Matcher caught = CATCH.matcher(message);
			int fish = caught.find() ? number(caught.group(1)) : -1;
			if (fish >= 0 && fishInNets >= 0)
			{
				setFish(Math.min(NET_CAPACITY, fishInNets + fish));
				if (fishInNets >= NET_CAPACITY)
				{
					warnNetsFull();
				}
			}
		}
	}

	/**
	 * Opening a net asks what to do with the fish in it and says how many there are, which puts the count
	 * right whatever it had drifted to.
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CHATMENU && boatPlace != null)
		{
			// The menu's lines are filled in after it loads.
			clientThread.invokeLater(this::readNetMenu);
		}
	}

	/**
	 * Stepping off the boat throws away whatever is in the nets, so they are empty once the player is no
	 * longer aboard: taken from the game's own flag rather than from where the player stands, which can
	 * look like being off the boat for a moment while the area loads. Also keeps track of which net slots
	 * have a net in them.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbit = event.getVarbitId();
		if (varbit == VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT && event.getValue() == 0)
		{
			resetFish(0);
		}
		else if (varbit == NET_SLOTS[0] || varbit == NET_SLOTS[1])
		{
			// Nets are only fitted or taken off ashore, and these arrive a few ticks after logging in, so the
			// answer is kept here as they change rather than asked for again every tick.
			netsFitted = readNetsFitted();
		}
		else if (varbit == NET_DEPTHS[0] || varbit == NET_DEPTHS[1])
		{
			boolean lowered = readNetsLowered();
			if (netsLowered && !lowered && client.getVarbitValue(VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT) == 1)
			{
				// Raising the nets keeps the fish line up a while after, but only while still aboard: nets
				// dropping out of the water as the player steps off or hops is not them being raised.
				fishActivityMillis = System.currentTimeMillis();
			}
			netsLowered = lowered;
		}
	}

	private void readNetMenu()
	{
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		Widget[] lines = options == null ? null : options.getDynamicChildren();
		if (lines == null || lines.length == 0 || lines[0].getText() == null)
		{
			return;
		}

		Matcher menu = NET_MENU.matcher(Text.removeTags(lines[0].getText()));
		int fish = menu.find() ? number(menu.group(1)) : -1;
		if (fish >= 0)
		{
			setFish(Math.min(NET_CAPACITY, fish));
		}
	}

	private void countInventory(ItemContainer inventory)
	{
		int filled = 0;
		for (Item item : inventory == null ? new Item[0] : inventory.getItems())
		{
			if (item.getId() >= 0)
			{
				filled++;
			}
		}

		// Fish don't stack, so the slots that filled are the fish that arrived.
		inventoryAdded = inventoryFilled < 0 ? -1 : Math.max(0, filled - inventoryFilled);
		inventoryFilled = filled;
		inventoryTick = client.getTickCount();
		if (takePending)
		{
			takePending = false;
			takeFromNets(inventoryAdded);
		}
	}

	private void takeFromNets(int taken)
	{
		setFish(taken < 0 || fishInNets < 0 ? -1 : Math.max(0, fishInNets - taken));
	}

	private void setFish(int fish)
	{
		fishInNets = fish;
		fishLabel = fishLabel(fish);
		if (fish >= 0 && fish < NET_CAPACITY)
		{
			// The nets have room again, so the next time they fill is worth a notification.
			netsFullWarned = false;
		}
	}

	private void warnNetsFull()
	{
		if (!netsFullWarned)
		{
			netsFullWarned = true;
			notifier.notify(config.notifyNetsFull(), "Your trawling nets are full.");
		}
	}

	/**
	 * Sets the count after the nets were just emptied or found empty, which keeps the fish line up for a
	 * while even though there is nothing in them. Anything that leaves fish in the nets, or an unknown count,
	 * shows the line anyway, so it goes through setFish.
	 */
	private void noteFish(int fish)
	{
		setFish(fish);
		fishActivityMillis = System.currentTimeMillis();
	}

	/**
	 * Sets the count without anything having been done with the nets, for logging in, stepping off the boat
	 * or the plugin starting, and forgets any recent activity so the fish line doesn't come up by itself.
	 */
	private void resetFish(int fish)
	{
		setFish(fish);
		fishActivityMillis = -1;
	}

	/**
	 * Whether the fish line is worth showing: whenever there are fish in the nets or the count is not known,
	 * whenever a net is lowered, since that is trawling under way, and otherwise for a minute after the nets
	 * were last emptied, found empty or raised.
	 */
	boolean fishLineWanted(long nowMillis)
	{
		return fishInNets != 0 || netsLowered
			|| (fishActivityMillis >= 0 && nowMillis - fishActivityMillis <= FISH_LINE_LINGER_MILLIS);
	}

	private static String fishLabel(int fish)
	{
		return "Fish: " + (fish < 0 ? "?" : Integer.toString(fish));
	}

	/**
	 * A count as the game writes it, in figures or in words, or -1 for one it isn't known to write.
	 */
	private static int number(String written)
	{
		if (!written.isEmpty() && written.length() < 5 && written.chars().allMatch(Character::isDigit))
		{
			return Integer.parseInt(written);
		}
		return NUMBER_WORDS.getOrDefault(written.toLowerCase(), -1);
	}

	/**
	 * How much bait is left that the nearest shoal takes, or -1 when that is not known. A shoal that takes
	 * either kind counts both together; every other shoal counts only the fine offcuts.
	 */
	private int baitLeft()
	{
		if (fineBait < 0 || nearestShoal == null)
		{
			return -1;
		}
		return takesPlainOffcuts(nearestShoal) ? plainBait + fineBait : fineBait;
	}

	/**
	 * A crewmate on the chum station found no offcuts in the hold, so the nearest shoal isn't baited and the
	 * hold has none of the offcuts it takes. On a shoal that takes plain offcuts that is both kinds; on one
	 * that takes only fine, the fine count is known to be empty, but the plain count is left alone while it
	 * isn't known, since the two are only ever known together.
	 */
	private void noBait()
	{
		baitFailedTick = client.getTickCount();
		baitedShoal = null;
		baited = false;
		if (nearestShoal != null && takesPlainOffcuts(nearestShoal))
		{
			plainBait = 0;
			fineBait = 0;
		}
		else if (plainBait >= 0)
		{
			fineBait = 0;
		}
		baitedLabel = label(baitLeft());
	}

	/**
	 * Takes one offcut off the count for a bait just laid on the nearest shoal. A shoal that takes plain
	 * offcuts takes fine ones too, but uses the plain first, so fine ones only go once the plain have run out.
	 */
	private void useBait()
	{
		if (fineBait < 0 || nearestShoal == null)
		{
			return;
		}

		if (takesPlainOffcuts(nearestShoal) && plainBait > 0)
		{
			plainBait--;
		}
		else if (fineBait > 0)
		{
			fineBait--;
		}
	}

	/**
	 * What routes.json knows about the kind of shoal this is, or null for one it has no entry for.
	 */
	private RouteData.Species speciesOf(Shoal shoal)
	{
		String name = SPECIES_BY_CLICKBOX.get(shoal.getClickbox());
		return speciesByName.get(name != null ? name : MIXED_BY_CLICKBOX.get(shoal.getClickbox()));
	}

	/**
	 * Whether plain fish offcuts bait this shoal as well as fine ones. A kind with no entry is taken to
	 * need fine ones, which every kind of shoal accepts.
	 */
	private boolean takesPlainOffcuts(Shoal shoal)
	{
		RouteData.Species species = speciesOf(shoal);
		return species != null && "any".equals(species.bait);
	}

	private static String label(int left)
	{
		return "Baited (" + (left < 0 ? "?" : Integer.toString(left)) + " left)";
	}

	/**
	 * Works out whether the nearest shoal is baited. The game records which step of its route a shoal was
	 * last baited at rather than how long the bait lasts, and never says when it wears off: the number
	 * stays where it is long after a bait, while the shoal swims on. Tested in game, a bait lasts until the
	 * shoal next arrives at a stop. Baited at a stop, it lasts the rest of that stop and the swim to the
	 * next; baited on the way, until the stop it is heading for. So a new number is a fresh bait on the
	 * nearest shoal, which stays baited until that shoal next arrives somewhere.
	 */
	private boolean stillBaited()
	{
		int step = client.getVarbitValue(VarbitID.SAILING_PLAYER_TRAWLING_SHOAL_BAITED_STEP);
		// A change on the tick a crewmate found nothing to bait with, or the one after, is that failed attempt.
		boolean laid = baitedStep != null && baitedStep != step && client.getTickCount() - baitFailedTick > 1;
		baitedStep = step;

		if (laid && nearestShoal != null)
		{
			baitedShoal = nearestShoal;
			baitedWasStopped = nearestShoal.stopped();
			ticksSinceBait = 0;
			useBait();
		}
		else if (baitedShoal != null)
		{
			ticksSinceBait++;
			boolean stopped = baitedShoal.stopped();
			// An arrival right after the bait is the shoal settling in as it was baited, which the bait
			// outlasts. Any later one is the next stop, where it runs out.
			if (stopped && !baitedWasStopped && ticksSinceBait > ARRIVAL_GRACE_TICKS)
			{
				baitedShoal = null;
			}
			baitedWasStopped = stopped;
		}
		return nearestShoal != null && nearestShoal == baitedShoal;
	}

	/**
	 * Whether anything should be drawn at all, as worked out on the last tick, which is as much of the
	 * Show guides setting as the overlays need to know.
	 */
	boolean showGuides()
	{
		return showGuides;
	}

	/**
	 * Whether the setting is satisfied, on a boat that is already known to be underfoot: either that is
	 * enough on its own, or the boat has to be fitted with a trawling net as well.
	 */
	private boolean guidesWanted()
	{
		// Only ever asked while aboard, so what is left to settle is whether a net has to be fitted too.
		if (config.showGuides() == TrawlingPlusConfig.ShowGuides.ALWAYS)
		{
			return true;
		}

		return netsFitted;
	}

	/**
	 * The player's own boat while they are stood on it, or null. Everyone aboard stands in the boat's own
	 * world view rather than the one the sea is in, and the boat is looked up straight from that view's id
	 * rather than searched for among every world entity in the scene. What comes back is checked to be
	 * that same view and the player's own boat, so standing on someone else's counts as not aboard.
	 */
	private WorldEntity boardedBoat()
	{
		Player player = client.getLocalPlayer();
		WorldView standing = player == null ? null : player.getWorldView();
		WorldView top = client.getTopLevelWorldView();
		if (standing == null || top == null || standing.isTopLevel() || standing.getId() < 0)
		{
			return null;
		}

		WorldEntity boat = top.worldEntities().byIndex(standing.getId());
		WorldView deck = boat == null ? null : boat.getWorldView();
		return deck != null && deck.getId() == standing.getId()
			&& boat.getOwnerType() == WorldEntity.OWNER_TYPE_SELF_PLAYER ? boat : null;
	}

	/**
	 * The shoal nearest the boat of the player, or null if there is no boat or no shoal to measure to.
	 */
	private Shoal nearest()
	{
		double[] afloat = boatPlace;
		if (afloat == null)
		{
			return null;
		}

		Shoal nearest = null;
		double nearestGap = Double.MAX_VALUE;
		for (Shoal shoal : shoals.values())
		{
			double[] at = shoal.position(client);
			if (at == null)
			{
				continue;
			}

			double gap = Math.hypot(at[0] - afloat[0], at[1] - afloat[1]);
			if (gap < nearestGap)
			{
				nearestGap = gap;
				nearest = shoal;
			}
		}
		return nearest;
	}

	/**
	 * A local point in world tile coordinates, including the fraction of a tile, or null.
	 */
	private double[] worldPlace(LocalPoint local)
	{
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		if (view == null)
		{
			return null;
		}

		return new double[]{
			view.getBaseX() + (double) (local.getX() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE,
			view.getBaseY() + (double) (local.getY() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE
		};
	}

	/**
	 * How long the shoal nearest the boat has left at its stop, in seconds, or -1 if there is no such
	 * shoal or it is on the move.
	 */
	double getSecondsAtStop()
	{
		return nearestShoal == null ? -1 : nearestShoal.secondsAtStop();
	}

	/**
	 * Reads what the fish inside a shoal say about it, in one walk of them: how deep it is swimming,
	 * from the animation they play, falling back to the depth its species rests at until they are
	 * close enough to be animating; and how much is left of the bar drawn over it while it sits at a
	 * stop, which the game draws the way it draws a health bar. Both come off the same handful of
	 * NPCs, so they are taken together rather than walking them again for each.
	 */
	private static void read(WorldEntity entity, ShoalDepth resting, Shoal shoal)
	{
		WorldView view = entity.getWorldView();
		ShoalDepth depth = resting;
		boolean swimming = false;
		int bar = -1;
		int scale = -1;

		for (NPC npc : view == null ? Collections.<NPC>emptyList() : view.npcs())
		{
			if (!swimming)
			{
				ShoalDepth animating = ShoalDepth.fromAnimation(npc.getAnimation());
				if (animating != null)
				{
					depth = animating;
					swimming = true;
				}
			}

			if (scale < 0 && npc.getHealthScale() > 0)
			{
				bar = npc.getHealthRatio();
				scale = npc.getHealthScale();
			}

			if (swimming && scale >= 0)
			{
				// Both found, so the rest of the shoal has nothing left to say.
				break;
			}
		}

		shoal.setDepth(depth);
		shoal.setStopBar(bar, scale);
	}

	private ShoalRoute nearestRoute(double x, double y, String species)
	{
		ShoalRoute nearest = null;
		double nearestOffset = MAX_ROUTE_OFFSET;
		for (ShoalRoute route : routes)
		{
			if (species != null && !species.equals(route.getSpecies()))
			{
				continue;
			}

			double offset = route.project(x, y).offset;
			if (offset <= nearestOffset)
			{
				nearest = route;
				nearestOffset = offset;
			}
		}
		return nearest;
	}

	private static boolean isShoalClickbox(int id)
	{
		return SPECIES_BY_CLICKBOX.containsKey(id) || MIXED_BY_CLICKBOX.containsKey(id);
	}

	private void clearShoals()
	{
		entities.clear();
		clickboxByView.clear();
		shoals.clear();
		showGuides = false;
		stopTracking();
	}

	/**
	 * Forgets everything read off the boat and the shoals around it, leaving the shoals themselves
	 * alone: they come and go with their own events, and the world map still marks the ones in view.
	 */
	private void stopTracking()
	{
		boat = null;
		boatPlace = null;
		nearestShoal = null;
		nearestRoute = null;
		contender = null;
		contenderTicks = 0;
		baitedStep = null;
		baited = false;
		baitedShoal = null;
		netsAtDepth = false;
		leavingShoal = null;
	}

	@Provides
	TrawlingPlusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TrawlingPlusConfig.class);
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

/**
 * Draws every shoal route on the world map, whether or not its sea is anywhere near, which doubles
 * as a picture of the seas covered so far. Drawn straight after the world map itself, underneath
 * RuneLite's own map markers and anything else drawn over the map afterwards.
 */
class TrawlingPlusMapOverlay extends Overlay
{
	private static final int THICKNESS = 2;
	private static final int ARROW = 8;
	private static final int SHOAL = 4;

	// Stretches of route that pass close to where sea creatures that attack boats spawn, and the skull and
	// crossbones marking each place they spawn close enough to a route to threaten it, placed among the spawns
	// that are that close. The plugin puts the skulls on the map as RuneLite world map points, which gives them
	// the game's style of tooltip. Drawn whenever routes are, on the world map only. Where each creature spawns is
	// never drawn itself.
	private static final Color DANGER_COLOUR = new Color(230, 40, 40);
	static final BufferedImage DANGER_ICON = dangerIcon();

	// How far apart the two points used to measure the map's zoom are, in tiles. Far enough that
	// rounding them to whole pixels barely matters.
	private static final int SCALE_TILES = 64;

	/**
	 * A small skull and crossbones, drawn once. White with a dark edge, so it reads on sea and land alike.
	 */
	private static BufferedImage dangerIcon()
	{
		BufferedImage icon = new BufferedImage(13, 13, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// The crossed bones, poking out from behind the skull at each corner.
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Color.BLACK);
		g.drawLine(2, 2, 10, 10);
		g.drawLine(10, 2, 2, 10);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Color.WHITE);
		g.drawLine(2, 2, 10, 10);
		g.drawLine(10, 2, 2, 10);

		// The skull: a round head over a narrower jaw, with two dark eyes.
		g.setColor(Color.BLACK);
		g.fillOval(2, 1, 9, 8);
		g.fillRect(4, 6, 5, 4);
		g.setColor(Color.WHITE);
		g.fillOval(3, 2, 7, 6);
		g.fillRect(5, 6, 3, 3);
		g.setColor(Color.BLACK);
		g.fillRect(4, 4, 2, 2);
		g.fillRect(7, 4, 2, 2);
		g.dispose();
		return icon;
	}

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;
	private final WorldMapOverlay worldMapOverlay;

	@Inject
	TrawlingPlusMapOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config,
		WorldMapOverlay worldMapOverlay)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.worldMapOverlay = worldMapOverlay;
		setPosition(OverlayPosition.DYNAMIC);
		// Right after the world map and at the lowest priority, so markers that RuneLite and other plugins draw
		// after the same interface at a higher priority sit on top of the routes rather than under them.
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
		setPriority(PRIORITY_LOW);
	}

	/**
	 * Whether the box a route fits inside reaches the part of the world the map is showing. The map
	 * scales and shifts the world without turning it, so the box stays a box on screen.
	 */
	private boolean onScreen(ShoalRoute route, Rectangle within)
	{
		int left = Integer.MAX_VALUE;
		int right = Integer.MIN_VALUE;
		int top = Integer.MAX_VALUE;
		int bottom = Integer.MIN_VALUE;
		for (double[] corner : route.corners())
		{
			Point at = worldMapOverlay.mapWorldPointToGraphicsPoint(
				new WorldPoint((int) Math.round(corner[0]), (int) Math.round(corner[1]), 0));
			if (at == null)
			{
				// Nothing to go on, so let it draw rather than hide a route that may well be there.
				return true;
			}

			left = Math.min(left, at.getX());
			right = Math.max(right, at.getX());
			top = Math.min(top, at.getY());
			bottom = Math.max(bottom, at.getY());
		}
		return within.intersects(left, top, Math.max(1, right - left), Math.max(1, bottom - top));
	}

	/**
	 * The part of the map showing the world, less the panels the world map puts over it (the overview and the
	 * list of maps), the same as RuneLite's own map markers leave out. A plain rectangle while neither is
	 * open, which keeps drawing on Java2D's quick path.
	 */
	private Shape mapArea(Rectangle within)
	{
		Area area = null;
		for (int panel : new int[]{InterfaceID.Worldmap.OVERVIEW_CONTAINER, InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0})
		{
			Widget widget = client.getWidget(panel);
			if (widget != null && !widget.isHidden())
			{
				if (area == null)
				{
					area = new Area(within);
				}
				area.subtract(new Area(widget.getBounds()));
			}
		}
		return area != null ? area : within;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		TrawlingPlusConfig.ShowOnMaps where = config.showOnMaps();
		if (client.getGameState() != GameState.LOGGED_IN
			|| where == TrawlingPlusConfig.ShowOnMaps.OFF
			|| where == TrawlingPlusConfig.ShowOnMaps.MINIMAP)
		{
			return null;
		}

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || map.isHidden())
		{
			return null;
		}

		// Deliberately not behind the Show guides setting: a map is for working out where to go, which
		// is something done before boarding a boat and fitting a net to it.
		Rectangle within = map.getBounds();

		// How far the map is zoomed, as the pixels a tile takes up each way. Measured off points a known
		// distance apart rather than read from a setting, and taken from the map itself so it holds
		// wherever the map happens to be scrolled to. North is up, so the second of these comes out
		// negative.
		Point origin = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(3200, 3200, 0));
		Point across = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(3200 + SCALE_TILES, 3200, 0));
		Point up = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(3200, 3200 + SCALE_TILES, 0));
		double perTileX = origin == null || across == null ? 0
			: (across.getX() - origin.getX()) / (double) SCALE_TILES;
		double perTileY = origin == null || up == null ? 0
			: (up.getY() - origin.getY()) / (double) SCALE_TILES;
		double pixelsPerTile = Math.abs(perTileX);

		// Which stretch of the world the map is showing, worked out by running the scale backwards from
		// the corners of the map. A point outside it cannot be drawn, and saying so in tiles costs two
		// comparisons, where finding out by placing it on the map costs an object and a lookup. Zoomed
		// in, that is most of a route: the map holds only a few dozen tiles at a time.
		double fromX = Double.NEGATIVE_INFINITY;
		double toX = Double.POSITIVE_INFINITY;
		double fromY = Double.NEGATIVE_INFINITY;
		double toY = Double.POSITIVE_INFINITY;
		if (origin != null && perTileX != 0 && perTileY != 0)
		{
			double[] edgeX = {3200 + (within.x - origin.getX()) / perTileX,
				3200 + (within.x + within.width - origin.getX()) / perTileX};
			double[] edgeY = {3200 + (within.y - origin.getY()) / perTileY,
				3200 + (within.y + within.height - origin.getY()) / perTileY};
			// A tile of slack, so a point just outside still draws the line running off the edge.
			fromX = Math.min(edgeX[0], edgeX[1]) - 1;
			toX = Math.max(edgeX[0], edgeX[1]) + 1;
			fromY = Math.min(edgeY[0], edgeY[1]) - 1;
			toY = Math.max(edgeY[0], edgeY[1]) + 1;
		}

		double leftX = fromX;
		double rightX = toX;
		double bottomY = fromY;
		double topY = toY;
		MapRoutes.Projection onto = (x, y) ->
		{
			if (x < leftX || x > rightX || y < bottomY || y > topY)
			{
				return null;
			}

			// The map only places whole tiles, which is a staircase once a tile is worth more than a
			// pixel or two, so the part of a tile is stepped out by hand from the scale measured above.
			int tileX = (int) Math.floor(x);
			int tileY = (int) Math.floor(y);
			Point at = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(tileX, tileY, 0));
			if (at == null)
			{
				return null;
			}

			int px = (int) Math.round(at.getX() + (x - tileX) * perTileX);
			int py = (int) Math.round(at.getY() + (y - tileY) * perTileY);
			// Scrolled off the edge of the map, or hidden behind its own border. The line ends at the
			// last point still on the map rather than being cut off exactly at its edge, which is near
			// enough and keeps the points beyond it from being drawn at all.
			return within.contains(px, py) ? new Point(px, py) : null;
		};

		Shape clip = graphics.getClip();
		graphics.clip(mapArea(within));

		for (ShoalRoute route : plugin.getRoutes())
		{
			// Whether any of the route could be on screen, from the box it fits inside, rather than by
			// working out where every point of it lands only to throw the lot away. The map is panned
			// and zoomed freely, so most of the time most routes are nowhere near it.
			if (!onScreen(route, within))
			{
				continue;
			}

			MapRoutes.route(graphics, config, route, onto, THICKNESS, pixelsPerTile,
				leftX, bottomY, rightX, topY);
			MapRoutes.dangerStretches(graphics, route, onto, DANGER_COLOUR, THICKNESS, pixelsPerTile,
				leftX, bottomY, rightX, topY);
			MapRoutes.arrows(graphics, config, route, onto, ARROW, pixelsPerTile,
				leftX, bottomY, rightX, topY, DANGER_COLOUR);
		}

		// Only a shoal the client is drawing in the world may be marked on the map. Shoals are dropped
		// as they despawn anyway, so this is belt and braces, but it says so in the code rather than
		// leaving it to be worked out from the order events arrive in.
		for (Shoal shoal : plugin.getShoals())
		{
			if (shoal.rendered(client))
			{
				MapRoutes.shoal(graphics, config, client, shoal, onto, SHOAL);
			}
		}

		graphics.setClip(clip);
		return null;
	}
}

package com.trawlingplus;

import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * A shoal in the scene and the route it has been matched to, if any.
 */
final class Shoal
{
	// How long the heading arrow takes to fade fully in or out, in milliseconds: about a game tick.
	private static final double FADE_MILLIS = 600;

	// Once the route to a new next stop has drawn itself out, how long the stop takes to fade in, in
	// milliseconds. How long the route takes to draw out is set in the config.
	private static final double STOP_REVEAL_MILLIS = 300;

	// How long a new section waits before it starts drawing out, in milliseconds. A shoal counts as
	// heading for its next stop a little before it has finished gliding into the one it is at, so this
	// gives it time to settle in first.
	private static final long REVEAL_DELAY_MILLIS = 500;

	private final WorldEntity entity;
	private ShoalRoute route;
	private int clickbox;
	// Where the shoal was last found along its route, so it can be followed past a crossing.
	private double routeDistance = -1;

	private double[] lastPosition;
	private double[] lastTarget;
	private ShoalDepth depth = ShoalDepth.UNKNOWN;

	// The bar the game draws over a shoal while it sits at a stop, which empties as the stop runs out,
	// and how long a stop on this shoal's route lasts. The bar is the same length whatever the route
	// but a stop is not, so without a known length there is nothing to turn the bar into a time.
	private int barLeft = -1;
	private int barScale;
	private int barStopTicks;
	private long stopEndsMillis = -1;
	private boolean sawNoBar;

	// A bar appearing this far below full did not just appear because a stop began. A shoal's world
	// entity turns up a tick or two before the fish inside it do, so it can look as though there was
	// no bar when really there was nothing to read it from yet.
	private static final int FRESH_SLACK = 6;
	// Hidden until the shoal is seen swimming, and whenever it sits still.
	private boolean headingArrowHidden = true;
	private double headingArrowOpacity;
	private long lastFadeMillis = -1;

	// The next stop the route is being drawn out to, and when that started.
	private int revealStop = -1;
	// The stop it was heading for before that, which it has just reached: kept on screen while the
	// shoal settles in there, then forgotten.
	private int arrivedStop = -1;
	private long revealStartMillis;

	Shoal(WorldEntity entity)
	{
		this.entity = entity;
	}

	ShoalRoute getRoute()
	{
		return route;
	}

	/**
	 * The clickbox object the shoal was found by, which says what species it is.
	 */
	int getClickbox()
	{
		return clickbox;
	}

	void setClickbox(int clickbox)
	{
		this.clickbox = clickbox;
	}

	void setRoute(ShoalRoute route)
	{
		if (route != this.route)
		{
			// Stop numbers belong to a route, so draw the new one out from the start.
			revealStop = -1;
			arrivedStop = -1;
			routeDistance = -1;
		}
		this.route = route;
	}

	/**
	 * Swaps in the same route with its line smoothed differently. Its stops are the same, so a next
	 * section that's drawing itself out carries on.
	 */
	void reshapeRoute(ShoalRoute route)
	{
		this.route = route;
	}

	/**
	 * Follows the shoal along its route, giving how far round it now is. Keeping hold of where it was
	 * is what stops it jumping to the other side of a crossing where a route doubles back on itself.
	 */
	double followRoute(double[] position)
	{
		routeDistance = route.project(position[0], position[1], routeDistance).distance;
		return routeDistance;
	}

	ShoalDepth getDepth()
	{
		return depth;
	}

	void setDepth(ShoalDepth depth)
	{
		this.depth = depth;
	}

	/**
	 * Takes the stop bar as it reads this tick. A bar that has gone means the shoal is on the move, and
	 * one that has gone up means it has settled at the next stop and the bar has been refilled.
	 */
	void setStopBar(int left, int scale)
	{
		if (left < 0)
		{
			// No bar, so the shoal is on the move and there is no stop to count down.
			stopEndsMillis = -1;
			sawNoBar = true;
		}
		else if (barLeft < 0 || left > barLeft)
		{
			// A stop has begun, so the clock is set running for as long as one lasts. When it began is
			// only known if the shoal was watched through the gap before it and the bar has turned up
			// full: a bar that was already part way down belongs to a stop that started before anyone
			// was looking, whether because the shoal was found mid stop or because it had not finished
			// loading, and that one is not counted at all.
			boolean fromTheStart = sawNoBar && scale > 0 && left >= scale - FRESH_SLACK;
			stopEndsMillis = fromTheStart
				? System.currentTimeMillis() + (long) barStopTicks * Constants.GAME_TICK_LENGTH
				: -1;
			sawNoBar = false;
		}

		barLeft = left;
		barScale = scale;
	}

	/**
	 * Takes how long a stop on this shoal's route lasts, in ticks, which is how long the clock is set for.
	 */
	void seedStopTicks(int ticks)
	{
		barStopTicks = ticks;
	}

	/**
	 * How long the shoal has left at this stop, in seconds, or -1 when that is not known exactly. It is
	 * only known for a stop that was watched from its first tick: a shoal found part way through one
	 * could only be guessed at from how far down its bar is, and a guess is worse than nothing here.
	 */
	double secondsAtStop()
	{
		if (barLeft < 0 || stopEndsMillis < 0)
		{
			return -1;
		}

		return Math.max(0, (stopEndsMillis - System.currentTimeMillis()) / 1000.0);
	}

	/**
	 * Whether the shoal is sitting at a stop, as of the last tick.
	 */
	boolean stopped()
	{
		return headingArrowHidden;
	}

	/**
	 * Tracks whether the shoal is swimming or sitting still, once per game tick. The heading arrow
	 * hides the tick the shoal stops and shows again the tick it moves off.
	 *
	 * Judged from where the shoal is heading whenever that can be read. The destination stops changing on
	 * the tick the last move is sent, and changes again the tick a new one is, where the drawn position
	 * only settles or sets off a tick later, once the client has glided it there. RuneLite confirmed that
	 * reading the destination of a shoal is fine. The position is the fallback when there is none.
	 */
	void update(double[] position, double[] target)
	{
		if (target != null)
		{
			if (lastTarget != null)
			{
				headingArrowHidden = target[0] == lastTarget[0] && target[1] == lastTarget[1];
			}
		}
		else if (lastPosition != null)
		{
			headingArrowHidden = position[0] == lastPosition[0] && position[1] == lastPosition[1];
		}
		lastPosition = position;
		lastTarget = target;
	}

	/**
	 * How opaque the heading arrow is right now, from 0 to 1. It moves towards shown or hidden a
	 * little on each call, so the arrow fades in and out instead of popping. Call once per frame.
	 */
	double headingArrowOpacity(long nowMillis)
	{
		if (lastFadeMillis >= 0)
		{
			double step = Math.max(0, nowMillis - lastFadeMillis) / FADE_MILLIS;
			headingArrowOpacity = headingArrowHidden
				? Math.max(0, headingArrowOpacity - step)
				: Math.min(1, headingArrowOpacity + step);
		}
		lastFadeMillis = nowMillis;

		// Smoothstep, so the fade eases in and out rather than changing at a constant rate.
		return headingArrowOpacity * headingArrowOpacity * (3 - 2 * headingArrowOpacity);
	}

	/**
	 * Notes the stop the shoal is heading for, once per frame. When it changes, the route to the new
	 * stop starts drawing itself out.
	 */
	void headFor(int nextStop, long nowMillis)
	{
		if (nextStop != revealStop)
		{
			arrivedStop = revealStop;
			revealStop = nextStop;
			revealStartMillis = nowMillis + REVEAL_DELAY_MILLIS;
		}
	}

	/**
	 * The stop the shoal has just reached, while it is still being shown, or -1.
	 */
	int arrivedStop()
	{
		return arrivedStop;
	}

	void clearArrivedStop()
	{
		arrivedStop = -1;
	}

	/**
	 * Whether the section to the next stop has started drawing out, rather than still waiting for the
	 * shoal to settle in.
	 */
	boolean revealStarted(long nowMillis)
	{
		return nowMillis >= revealStartMillis;
	}

	/**
	 * How much of the route to the next stop is drawn so far, from 0 to 1, when it takes the given
	 * time to draw out.
	 */
	double routeReveal(long nowMillis, long revealMillis)
	{
		double t = Math.min(1, Math.max(0, nowMillis - revealStartMillis) / (double) revealMillis);
		// Sets off gently and settles into the stop, but without creeping in, which read as dragging on:
		// it arrives at a third of its average speed rather than coming to a crawl.
		return t * t * (8 - 5 * t) / 3;
	}

	/**
	 * How opaque the next stop is, from 0 to 1. It fades in once the route has been drawn out to it.
	 */
	double nextStopReveal(long nowMillis, long revealMillis)
	{
		double t = Math.min(1, Math.max(0, nowMillis - revealStartMillis - revealMillis) / STOP_REVEAL_MILLIS);
		return t * t * (3 - 2 * t);
	}

	/**
	 * The world view the shoal swims around in, which is normally the top-level one.
	 */
	WorldView parentView(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		return local == null ? null : client.getWorldView(local.getWorldView());
	}

	/**
	 * Whether the shoal is being drawn in the world right now. Only a shoal the client is rendering
	 * may be marked on a map: a remembered position is not the plugin's to show, and one that has
	 * swum out of range is no longer the plugin's to know.
	 */
	boolean rendered(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		if (view == null)
		{
			return false;
		}

		// Inside the scene the client is drawing, rather than the wider area it has loaded around it.
		return local.getX() >= 0 && local.getY() >= 0
			&& local.getX() < view.getSizeX() * Perspective.LOCAL_TILE_SIZE
			&& local.getY() < view.getSizeY() * Perspective.LOCAL_TILE_SIZE;
	}

	/**
	 * Where the shoal is swimming to in world tiles: the spot the server last sent, which the client glides
	 * it towards until the next tick. Null when it cannot be read.
	 */
	double[] target(Client client)
	{
		LocalPoint local = entity.getTargetLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		return view == null ? null : toWorld(view, local);
	}

	/**
	 * The shoal's position in world tile coordinates, including the fraction of a tile, or null.
	 */
	double[] position(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		return view == null ? null : toWorld(view, local);
	}

	private static double[] toWorld(WorldView view, LocalPoint local)
	{
		return new double[]{
			view.getBaseX() + (double) (local.getX() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE,
			view.getBaseY() + (double) (local.getY() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE
		};
	}
}

package com.trawlingplus;

import java.util.List;

/**
 * The shape of routes.json, which tools/generate_routes.py builds from the routes recorded in game
 * in tools/recorded_routes.json.
 */
class RouteData
{
	List<Species> species;

	static class Species
	{
		String name;
		// "any" where both fish offcuts and fine fish offcuts bait this kind of shoal, "fine" where only
		// fine fish offcuts do.
		String bait;
		List<Route> routes;
	}

	static class Route
	{
		String name;
		// How long a shoal sits at each stop on this route, in ticks, or 0 where it has not been timed
		// yet. Different species sit for very different lengths, so there is no sensible default.
		int stopTicks;
		double[][] stops;
		double[][] path;
		// Stretches marked safe by hand in routes.json despite sitting close to where a sea creature that
		// attacks boats spawns, as [x, y, tiles] circles, or null where none apply.
		double[][] safe;
		// Where sea creatures that attack boats spawn close enough to threaten this route, place by place, or
		// null where none do. From the OSRS wiki (Boat combat, each creature page), folded in by hand once
		// under the route each place is close enough to threaten; a place is never split between routes.
		List<Threat> threats;
	}

	static class Threat
	{
		String creature;
		int combat;
		int[][] points;
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class TrawlingPlusOverlay extends Overlay
{
	// Stops are drawn as a square this many tiles across, roughly the size of a shoal.
	private static final int STOP_SIZE = 3;

	// How far a shoal can be fished from, in tiles along each axis. It is the same for every kind of
	// shoal, but it is not measured from the middle of the boat: it is measured from a point towards the
	// bow, so a boat pointing its bow at a shoal can fish it from further away than one pointing its
	// stern. Measured on a sloop against bluefin, halibut and glistening shoals, parked still. The edge
	// shifts by about half a tile with the way the boat faces, so this sits between where fishing always
	// works and where it sometimes still does.
	private static final double FISHABLE_REACH = 8.7;

	// That point on the boat, in local units ahead of its middle towards the bow: two and a quarter
	// tiles. The bow is the low end of the boat's own view, the helm the high end.
	private static final int FISHING_POINT_AHEAD = Perspective.LOCAL_TILE_SIZE * 9 / 4;

	// The dot marking that point on the boat, in pixels across.
	private static final int FISHING_POINT_SIZE = 5;

	// How long the dot takes to fade fully in or out as the fishable area comes and goes, in milliseconds.
	private static final double FISHING_POINT_FADE_MILLIS = 500;

	// The area the game itself uses is a square lined up with the map: a shoal can be fished while that
	// point on the boat is within the reach of it along both the x and the y axis. A circle of the same
	// reach sits just inside it, for anyone who would rather have the rounder guide.
	//
	// Either shape is drawn through points spaced around it rather than only a few corners, so one
	// running off the loaded map still draws the part that is on it, and it follows the height of the
	// water it crosses. Where each sits never changes, so both are worked out once here, as fractions of
	// the reach: the square's south side west to east, then east, north and west the same way round, and
	// the circle anticlockwise from the east.
	private static final int AREA_POINTS_PER_SIDE = 16;
	private static final int AREA_POINTS = AREA_POINTS_PER_SIDE * 4;
	private static final double[] SQUARE_X = new double[AREA_POINTS];
	private static final double[] SQUARE_Y = new double[AREA_POINTS];
	private static final double[] CIRCLE_X = new double[AREA_POINTS];
	private static final double[] CIRCLE_Y = new double[AREA_POINTS];

	static
	{
		for (int step = 0; step < AREA_POINTS_PER_SIDE; step++)
		{
			double along = -1 + 2.0 * step / AREA_POINTS_PER_SIDE;
			int south = step;
			int east = south + AREA_POINTS_PER_SIDE;
			int north = east + AREA_POINTS_PER_SIDE;
			int west = north + AREA_POINTS_PER_SIDE;
			SQUARE_X[south] = along;
			SQUARE_Y[south] = -1;
			SQUARE_X[east] = 1;
			SQUARE_Y[east] = along;
			SQUARE_X[north] = -along;
			SQUARE_Y[north] = 1;
			SQUARE_X[west] = -1;
			SQUARE_Y[west] = -along;
		}
		for (int step = 0; step < AREA_POINTS; step++)
		{
			double angle = 2 * Math.PI * step / AREA_POINTS;
			CIRCLE_X[step] = Math.cos(angle);
			CIRCLE_Y[step] = Math.sin(angle);
		}
	}

	// How far above the deck the display at the helm floats, in local units: about two tiles, which
	// clears the mast and the crew.
	private static final int HELM_TEXT_HEIGHT = 250;

	// A dark box behind the display at the helm, so its text reads against the water whatever its colour.
	private static final Color HELM_BACKGROUND = new Color(0, 0, 0, 150);
	private static final int HELM_PADDING = 3;

	// How long the display at the helm takes to fade fully in or out, in milliseconds.
	private static final double HELM_FADE_MILLIS = 500;

	// The gap between the depth and the tick that follows it once every net is set to that depth.
	private static final int TICK_GAP = 4;

	// The lines of the display at the helm. The depth holds the bottom line so the display keeps its
	// place on the boat however many of the others are showing.
	private static final int DEPTH_LINE = 0;
	private static final int TIME_LINE = 1;
	private static final int BAITED_LINE = 2;
	private static final int FISH_LINE = 3;
	private static final int HOLD_LINE = 4;
	private static final int HELM_LINES = 5;

	// The warning on top of the display while the hold is full, pulsing between two colours, from one to
	// the other and back in this long.
	private static final String HOLD_FULL = "Hold full";
	private static final Color HOLD_FULL_COLOUR = new Color(255, 70, 40);
	private static final Color HOLD_FULL_PULSE_COLOUR = new Color(255, 200, 60);
	private static final long HOLD_FULL_PULSE_MILLIS = 1000;

	// The stops' faint fill, as RuneLite draws a highlighted tile.
	private static final Color STOP_FILL = new Color(0, 0, 0, 50);

	// A direction arrow's length in tiles at 100% scaling, and its shape as fractions of its length:
	// half its width, and how far behind its middle the notch between its wings sits.
	private static final double ARROW_LENGTH = 1.5;
	private static final double ARROW_HALF_WIDTH = 0.4;
	private static final double ARROW_NOTCH = 0.2;

	// The same for the arrow marking where a shoal is and which way it's heading, which also leads a
	// route as it draws out to the next stop. The heading arrow is drawn last, so it sits on top of
	// everything else.
	private static final double SHOAL_ARROW_LENGTH = 2.4;
	private static final double SHOAL_ARROW_HALF_WIDTH = 1.0 / 2.4;
	private static final double SHOAL_ARROW_NOTCH = 0.45 / 2.4;

	// The fishable area, and the stroke it is drawn with, kept between frames: the shape is redrawn every
	// frame but never changes size, and the thickness only changes when a setting does.
	private final Polygon area = new Polygon();
	private Stroke areaStroke;
	private int areaThickness;

	// How far faded in the fishing point dot is, and when that was last worked out.
	private double fishingPointFade;
	private long lastFishingPointMillis = -1;

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;

	// How far faded in each line of the display at the helm is, by line.
	private final double[] helmFades = new double[HELM_LINES];
	private long lastHelmFadeMillis = -1;
	private ShoalDepth fadingDepth = ShoalDepth.UNKNOWN;

	@Inject
	TrawlingPlusOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Routes included: there is no point being shown where the fish are by a boat that cannot
		// catch them, though how strict to be about that is the Show guides setting.
		if (client.getGameState() != GameState.LOGGED_IN || !plugin.showGuides())
		{
			return null;
		}

		Object antialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// With the route line, stops and direction arrows all off, only the shoals' heading arrows are drawn.
		boolean routes = config.showRouteLine() || config.showStops() || config.showDirectionArrows();

		// Where each shoal is on its route, found once per frame and shared by everything drawn below.
		// Placing a shoal searches its route, so it is skipped when nothing on screen needs it.
		long now = System.currentTimeMillis();
		List<PlacedShoal> shoals = routes || config.showShoalHeadingArrow()
			? placeShoals(now)
			: Collections.emptyList();

		if (routes)
		{
			if (config.routeDisplay() == TrawlingPlusConfig.RouteDisplay.WHOLE_ROUTE)
			{
				drawAllRoutes(graphics, shoals, now);
			}
			else
			{
				drawNextStops(graphics, shoals, now);
			}
		}
		drawShoalArrows(graphics, shoals, now);
		boolean areaDrawn = config.showFishableArea() && drawFishableArea(graphics);
		// Switched off, the dot goes at once like anything else; it only fades as the area comes and goes.
		if (config.showFishableArea() && config.showFishingPoint())
		{
			drawFishingPoint(graphics, areaDrawn, now);
		}
		else
		{
			fishingPointFade = 0;
			lastFishingPointMillis = -1;
		}
		drawHelm(graphics);

		if (antialiasing != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialiasing);
		}
		return null;
	}

	/**
	 * Every shoal that's matched to a route and can be placed on it this frame.
	 */
	private List<PlacedShoal> placeShoals(long now)
	{
		List<PlacedShoal> placed = new ArrayList<>();
		for (Shoal shoal : plugin.getShoals())
		{
			ShoalRoute route = shoal.getRoute();
			WorldView view = shoal.parentView(client);
			double[] position = shoal.position(client);
			if (route != null && view != null && position != null)
			{
				placed.add(new PlacedShoal(shoal, route, view, position, now));
			}
		}
		return placed;
	}

	private void drawAllRoutes(Graphics2D graphics, List<PlacedShoal> shoals, long now)
	{
		// Only the route the boat is nearest, whether or not its shoal is in view. Drawing every route
		// that reaches into the loaded scene means several at once in seas where they run close, which
		// says little and costs a good deal.
		WorldView view = client.getTopLevelWorldView();
		ShoalRoute route = plugin.getNearestRoute();
		if (view == null || route == null)
		{
			return;
		}

		int beyond = tilesBeyondScene(view);
		if (route.overlaps(view.getBaseX() - beyond, view.getBaseY() - beyond,
			view.getBaseX() + view.getSizeX() + beyond, view.getBaseY() + view.getSizeY() + beyond))
		{
			drawWholeRoute(graphics, view, route, shoals, now);
		}
	}

	private void drawNextStops(Graphics2D graphics, List<PlacedShoal> shoals, long now)
	{
		for (PlacedShoal placed : shoals)
		{
			drawToNextStop(graphics, placed, now);
		}
	}

	private void drawWholeRoute(Graphics2D graphics, WorldView view, ShoalRoute route, List<PlacedShoal> shoals,
		long now)
	{
		if (config.showRouteLine())
		{
			// Only the runs of the route that reach the loaded map. Most of a route is well outside it,
			// and a run can be dismissed in four comparisons instead of asking the same of all sixty
			// four points inside it.
			int beyond = tilesBeyondScene(view);
			double fromX = view.getBaseX() - beyond;
			double fromY = view.getBaseY() - beyond;
			double toX = view.getBaseX() + view.getSizeX() + beyond;
			double toY = view.getBaseY() + view.getSizeY() + beyond;

			Line line = new Line();
			for (int block = 0; block < route.blockCount(); block++)
			{
				if (!route.blockWithin(block, fromX, fromY, toX, toY))
				{
					// Nowhere near, so the line picks up again wherever the route comes back.
					line.add(null);
					continue;
				}

				for (int sample = route.blockFrom(block); sample < route.blockTo(block); sample++)
				{
					line.add(toCanvas(view, route.sampleX(sample), route.sampleY(sample)));
				}
			}

			// Closing the loop, so the last run joins back onto the first.
			line.add(toCanvas(view, route.sampleX(0), route.sampleY(0)));
			drawLine(graphics, line);
		}

		if (config.showDirectionArrows())
		{
			drawArrows(graphics, view, route, 0, route.length());
		}

		if (config.showStops())
		{
			boolean[] next = nextStops(route, shoals);
			double[] shown = stopsShown(route, shoals);
			for (int stop = 0; stop < route.stopCount(); stop++)
			{
				if (shown[stop] > 0)
				{
					drawStop(graphics, view, route, stop, next[stop] ? config.nextStopColour() : config.stopColour(),
						shown[stop]);
				}
			}
		}

		drawHeadArrows(graphics, view, route, shoals, now);
	}

	/**
	 * Which of a route's stops are the next stop of a shoal on it. A route whose shoal isn't in the
	 * loaded scene has none.
	 */
	private static boolean[] nextStops(ShoalRoute route, List<PlacedShoal> shoals)
	{
		boolean[] next = new boolean[route.stopCount()];
		for (PlacedShoal placed : shoals)
		{
			if (placed.route == route)
			{
				next[placed.next] = true;
			}
		}
		return next;
	}

	/**
	 * How much of each of a route's stops to show in Whole route, from 0 to 1. The stop a shoal is sitting
	 * at is hidden, fading out with its heading arrow as it settles in; every other stop shows in full.
	 */
	private static double[] stopsShown(ShoalRoute route, List<PlacedShoal> shoals)
	{
		double[] shown = new double[route.stopCount()];
		for (int stop = 0; stop < shown.length; stop++)
		{
			shown[stop] = 1;
		}

		for (PlacedShoal placed : shoals)
		{
			if (placed.route != route || !placed.shoal.stopped())
			{
				continue;
			}

			// Sitting at a stop moves a shoal's next stop on to the one after, so the one it is at comes just
			// before that. Only when it really is there, rather than stopped short of it.
			int at = (placed.next + shown.length - 1) % shown.length;
			double apart = Math.abs(placed.distance - route.stopDistance(at)) % route.length();
			if (Math.min(apart, route.length() - apart) <= ShoalRoute.AT_STOP_TILES)
			{
				shown[at] = Math.min(shown[at], placed.headingOpacity);
			}
		}
		return shown;
	}

	/**
	 * In Whole route the line is already drawn, so all that is left of the animation is the arrow at its
	 * head. When a shoal sets off for a new stop, the arrow runs along the route from the shoal to that
	 * stop over the animation duration, then fades as it arrives, the same as it does in Next stop only.
	 */
	private void drawHeadArrows(Graphics2D graphics, WorldView view, ShoalRoute route, List<PlacedShoal> shoals,
		long now)
	{
		if (!config.revealNextSection())
		{
			return;
		}

		long revealMillis = revealMillis();
		for (PlacedShoal placed : shoals)
		{
			if (placed.route != route)
			{
				continue;
			}

			// Kept up to date whether or not the arrow is drawn, so switching direction arrows on does
			// not replay a stretch the shoal set off along a while ago.
			placed.shoal.headFor(placed.next, now);
			double opacity = 1 - placed.shoal.nextStopReveal(now, revealMillis);
			if (!config.showDirectionArrows() || opacity <= 0 || !placed.shoal.revealStarted(now))
			{
				continue;
			}

			double stretch = route.forward(placed.distance, route.stopDistance(placed.next));
			double drawn = stretch * placed.shoal.routeReveal(now, revealMillis);
			double tipLength = shoalArrowLength();
			Path2D tip = arrowhead(view, onRoute(route, placed.distance + drawn, tipLength), tipLength,
				SHOAL_ARROW_HALF_WIDTH, SHOAL_ARROW_NOTCH);
			if (tip != null)
			{
				graphics.setColor(withOpacity(config.directionArrowColour(), opacity));
				graphics.fill(tip);
			}
		}
	}

	/**
	 * How long a new stretch of route takes to animate, in milliseconds.
	 */
	private long revealMillis()
	{
		return 1000L * Math.max(TrawlingPlusConfig.MIN_ANIMATION_SECONDS,
			Math.min(TrawlingPlusConfig.MAX_ANIMATION_SECONDS, config.animationDuration()));
	}

	private void drawToNextStop(Graphics2D graphics, PlacedShoal placed, long now)
	{
		ShoalRoute route = placed.route;
		WorldView view = placed.view;
		double distance = placed.distance;
		int next = placed.next;
		double stretch = route.forward(distance, route.stopDistance(next));

		// When the shoal moves on to a new next stop, the route to it draws itself out from the shoal,
		// arrows appearing as it reaches them, and the stop fades in once the route gets there.
		placed.shoal.headFor(next, now);

		// The stop the shoal has just reached stays until it settles in there, fading out with the heading
		// arrow, rather than vanishing the moment the shoal counts as heading for the next one.
		int arrived = placed.shoal.arrivedStop();
		if (arrived >= 0)
		{
			if (placed.headingOpacity <= 0)
			{
				placed.shoal.clearArrivedStop();
			}
			else if (config.showStops())
			{
				drawStop(graphics, view, route, arrived, config.nextStopColour(), placed.headingOpacity);
			}
		}

		double routeReveal = 1;
		double stopReveal = 1;
		if (config.revealNextSection())
		{
			long revealMillis = revealMillis();
			routeReveal = placed.shoal.routeReveal(now, revealMillis);
			stopReveal = placed.shoal.nextStopReveal(now, revealMillis);
			if (!placed.shoal.revealStarted(now))
			{
				// Waiting for the shoal to settle in before the way to its next stop is drawn.
				return;
			}
		}
		double drawn = stretch * routeReveal;

		if (config.showRouteLine())
		{
			int from = route.sampleAt(distance);
			int steps = Math.floorMod(route.sampleAt(route.stopDistance(next)) - from, route.sampleCount());

			// Starts where the shoal is along the route rather than where the shoal itself is, so the line
			// only ever gets shorter as the shoal swims along it. Joining it to the shoal instead leaves a
			// first piece that swings about, since a smoothed route never runs exactly through the shoal.
			Line line = new Line();
			double[] start = route.pointAt(distance);
			line.add(toCanvas(view, start[0], start[1]));
			for (int step = 0; step < steps; step++)
			{
				int sample = (from + step) % route.sampleCount();
				if (route.forward(distance, route.sampleDistance(sample)) >= drawn)
				{
					break;
				}
				line.add(toCanvas(view, route.sampleX(sample), route.sampleY(sample)));
			}

			// Ends along the route too, level with the stop once it has drawn all the way there, rather than
			// at the stop itself: a smoothed route passes beside a stop, and joining the two leaves a hook.
			double[] end = route.pointAt(distance + drawn);
			line.add(toCanvas(view, end[0], end[1]));
			drawLine(graphics, line);
		}

		if (config.showDirectionArrows())
		{
			drawArrows(graphics, view, route, distance, drawn);
		}

		if (config.showStops() && stopReveal > 0)
		{
			drawStop(graphics, view, route, next, config.nextStopColour(), stopReveal);
		}

		// An arrow leads the route as it draws out, and fades away as the stop fades in.
		double tipOpacity = 1 - stopReveal;
		if (config.showDirectionArrows() && tipOpacity > 0)
		{
			double tipLength = shoalArrowLength();
			Path2D tip = arrowhead(view, onRoute(route, distance + drawn, tipLength), tipLength, SHOAL_ARROW_HALF_WIDTH, SHOAL_ARROW_NOTCH);
			if (tip != null)
			{
				graphics.setColor(withOpacity(config.directionArrowColour(), tipOpacity));
				graphics.fill(tip);
			}
		}
	}

	/**
	 * Draws the display at the helm of the player's boat: the depth, time left at the stop, fish in the
	 * nets, bait and the hold full warning, each line fading in and out on its own.
	 */
	private void drawHelm(Graphics2D graphics)
	{
		if (!config.showHeadsUpDisplay())
		{
			return;
		}

		// Each line of the display stands on its own. Only the depth waits on a depth being known; the
		// rest have nothing to do with it and are not held up by it.
		WorldEntity boat = plugin.getBoat();
		ShoalDepth depth = boat == null ? ShoalDepth.UNKNOWN : plugin.getNearestDepth();
		if (depth != ShoalDepth.UNKNOWN)
		{
			// Kept while the text fades out, so it does not change word on the way.
			fadingDepth = depth;
		}

		double seconds = boat == null ? -1 : plugin.getSecondsAtStop();
		long now = System.currentTimeMillis();
		boolean[] wanted = new boolean[HELM_LINES];
		wanted[DEPTH_LINE] = boat != null && config.showShoalDepth() && depth != ShoalDepth.UNKNOWN;
		wanted[TIME_LINE] = boat != null && config.showTimeAtStop() && seconds >= 0;
		wanted[BAITED_LINE] = boat != null && config.showBaited() && plugin.isBaited();
		wanted[FISH_LINE] = boat != null && config.showFishInNets() && plugin.netsFitted() && plugin.fishLineWanted(now);
		wanted[HOLD_LINE] = boat != null && config.showFishInNets() && plugin.isHoldFull();

		// A line coming or going while another holds the pill up is a change inside something already
		// on screen, so it happens at once. The fade is for the display itself arriving or leaving.
		double step = lastHelmFadeMillis < 0 ? 0
			: Math.max(0, now - lastHelmFadeMillis) / HELM_FADE_MILLIS;
		boolean[] wasUp = new boolean[HELM_LINES];
		for (int line = 0; line < HELM_LINES; line++)
		{
			wasUp[line] = helmFades[line] > 0;
		}

		double[] opacity = new double[HELM_LINES];
		for (int line = 0; line < HELM_LINES; line++)
		{
			// Another line already holding the pill up means this one is changing inside a display that
			// is already on screen, so it changes at once rather than fading.
			opacity[line] = fade(line, wanted[line], step, othersUp(wasUp, line));
		}
		lastHelmFadeMillis = now;

		WorldView deck = boat == null ? null : boat.getWorldView();
		WorldEntityConfig hull = boat == null ? null : boat.getConfig();
		if (deck == null || hull == null)
		{
			return;
		}

		// The lines that are actually showing, bottom first, so a gap in the middle closes up.
		String[] text = new String[HELM_LINES];
		Color[] colour = new Color[HELM_LINES];
		double[] showing = new double[HELM_LINES];
		int[] width = new int[HELM_LINES];
		FontMetrics letters = graphics.getFontMetrics();
		boolean ticked = opacity[DEPTH_LINE] > 0 && config.showDepthTick() && plugin.isAtDepth();
		int count = 0;
		int depthAt = -1;

		if (opacity[DEPTH_LINE] > 0 && fadingDepth != ShoalDepth.UNKNOWN)
		{
			depthAt = count;
			text[count] = fadingDepth.toString();
			colour[count] = depthColour(fadingDepth);
			showing[count] = opacity[DEPTH_LINE];
			width[count] = letters.stringWidth(text[count])
				+ (ticked ? TICK_GAP + TrawlingPlusNetOverlay.TICK_WIDTH : 0);
			count++;
		}
		if (opacity[BAITED_LINE] > 0)
		{
			text[count] = plugin.getBaitedLabel();
			// Text, so drawn solid whatever the picked colour says.
			colour[count] = TrawlingPlusNetOverlay.opaque(config.baitedColour());
			showing[count] = opacity[BAITED_LINE];
			width[count] = letters.stringWidth(text[count]);
			count++;
		}
		if (opacity[FISH_LINE] > 0)
		{
			text[count] = plugin.getFishLabel();
			colour[count] = TrawlingPlusNetOverlay.opaque(config.fishInNetsColour());
			showing[count] = opacity[FISH_LINE];
			width[count] = letters.stringWidth(text[count]);
			count++;
		}
		if (opacity[TIME_LINE] > 0)
		{
			text[count] = Math.max(0, Math.round(seconds)) + "s";
			colour[count] = TrawlingPlusNetOverlay.opaque(config.timeLeftColour());
			showing[count] = opacity[TIME_LINE];
			width[count] = letters.stringWidth(text[count]);
			count++;
		}
		if (opacity[HOLD_LINE] > 0)
		{
			// Eased back and forth rather than blinking, starting and ending on the first colour.
			double pulse = (1 - Math.cos(2 * Math.PI * (now % HOLD_FULL_PULSE_MILLIS) / HOLD_FULL_PULSE_MILLIS)) / 2;
			text[count] = HOLD_FULL;
			colour[count] = blend(HOLD_FULL_COLOUR, HOLD_FULL_PULSE_COLOUR, pulse);
			showing[count] = opacity[HOLD_LINE];
			width[count] = letters.stringWidth(HOLD_FULL);
			count++;
		}

		if (count == 0)
		{
			return;
		}

		// The helm sits a quarter of the hull length behind the middle of the boat, and the text a
		// tile and a half further back again. A hull an odd number of tiles wide has its middle
		// tile half a tile off the middle of the view.
		int across = deck.getSizeX() * Perspective.LOCAL_TILE_SIZE / 2;
		if ((hull.getBoundsWidth() / Perspective.LOCAL_TILE_SIZE) % 2 != 0)
		{
			across -= Perspective.LOCAL_HALF_TILE_SIZE;
		}
		LocalPoint atStern = new LocalPoint(across,
			deck.getSizeY() * Perspective.LOCAL_TILE_SIZE / 2 + hull.getBoundsHeight() / 4
				+ Perspective.LOCAL_TILE_SIZE * 3 / 2, deck);
		LocalPoint afloatAtStern = boat.transformToMainWorld(atStern);
		if (afloatAtStern == null)
		{
			return;
		}

		Point at = Perspective.getCanvasTextLocation(client, graphics, afloatAtStern, text[0],
			HELM_TEXT_HEIGHT);
		if (at == null)
		{
			return;
		}

		// getCanvasTextLocation gives the left end of the bottom line's baseline; the stack grows up
		// from there and the pill grows with it.
		int lineHeight = letters.getHeight();
		int wide = 0;
		double solid = 0;
		for (int line = 0; line < count; line++)
		{
			wide = Math.max(wide, width[line]);
			solid = Math.max(solid, showing[line]);
		}
		int left = at.getX() + (letters.stringWidth(text[0]) - wide) / 2;
		int top = at.getY() - letters.getAscent() - (count - 1) * lineHeight;

		// One pill around the lot, as opaque as whichever line is showing the most, so it does not
		// flicker as one of them fades while the others stay.
		graphics.setColor(withOpacity(HELM_BACKGROUND, solid));
		graphics.fillRoundRect(left - HELM_PADDING, top - HELM_PADDING,
			wide + HELM_PADDING * 2, lineHeight * count + HELM_PADDING * 2, 6, 6);

		for (int line = 0; line < count; line++)
		{
			int from = left + (wide - width[line]) / 2;
			int baseline = at.getY() - line * lineHeight;
			line(graphics, text[line], from, baseline, colour[line], showing[line]);
			if (line == depthAt && ticked)
			{
				TrawlingPlusNetOverlay.drawTick(graphics,
					from + letters.stringWidth(text[line]) + TICK_GAP,
					baseline - letters.getAscent() / 2,
					withOpacity(TrawlingPlusNetOverlay.TICK, showing[line]));
			}
		}
	}

	/**
	 * Draws one piece of a route's line.
	 */
	private void drawLine(Graphics2D graphics, Line line)
	{
		// Round joins and caps so the short segments the curve is drawn with blend into one smooth line.
		graphics.setColor(config.routeColour());
		graphics.setStroke(new BasicStroke(config.routeLineThickness().pixels(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.draw(line.path);
	}

	/**
	 * The colour a depth is shown in.
	 */
	private Color depthColour(ShoalDepth depth)
	{
		switch (depth)
		{
			case SHALLOW:
				return TrawlingPlusNetOverlay.opaque(config.shallowDepthColour());
			case DEEP:
				return TrawlingPlusNetOverlay.opaque(config.deepDepthColour());
			default:
				return TrawlingPlusNetOverlay.opaque(config.moderateDepthColour());
		}
	}

	/**
	 * Whether any line other than the given one is showing.
	 */
	private static boolean othersUp(boolean[] up, int except)
	{
		for (int line = 0; line < up.length; line++)
		{
			if (line != except && up[line])
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Moves one line of the display towards shown or hidden, and gives back how opaque it now is. A
	 * line held up by one of the others changes at once instead of fading.
	 */
	private double fade(int line, boolean showing, double step, boolean atOnce)
	{
		if (atOnce)
		{
			helmFades[line] = showing ? 1 : 0;
		}
		else
		{
			helmFades[line] = showing ? Math.min(1, helmFades[line] + step)
				: Math.max(0, helmFades[line] - step);
		}

		// Smoothstep, so the fade eases in and out rather than changing at a constant rate.
		double faded = helmFades[line];
		return faded * faded * (3 - 2 * faded);
	}

	/**
	 * One line of the helm text, with the shadow drawn here rather than with OverlayUtil so that it
	 * fades along with the text.
	 */
	private static void line(Graphics2D graphics, String text, int left, int baseline, Color colour,
		double opacity)
	{
		graphics.setColor(withOpacity(Color.BLACK, opacity));
		graphics.drawString(text, left + 1, baseline + 1);
		graphics.setColor(withOpacity(colour, opacity));
		graphics.drawString(text, left, baseline);
	}

	/**
	 * Draws the route's arrows that fall within a stretch of it, starting at a distance round the route.
	 * Arrows sit at fixed places round the route, so they don't slide along as the shoal swims.
	 */
	private void drawArrows(Graphics2D graphics, WorldView view, ShoalRoute route, double from, double stretch)
	{
		// Clamped as well as limited in the settings panel, since a spacing of 0 would never finish.
		int spacing = Math.max(TrawlingPlusConfig.MIN_ARROW_SPACING,
			Math.min(TrawlingPlusConfig.MAX_ARROW_SPACING, config.directionArrowSpacing()));
		double length = scaled(ARROW_LENGTH, config.directionArrowScale());

		// The first arrow sits one spacing in from the start of the route, so where the loop closes, its
		// last arrow and first arrow are never closer than the spacing.
		graphics.setColor(config.directionArrowColour());
		for (int arrow = 1; arrow * spacing < route.length(); arrow++)
		{
			double at = arrow * spacing;
			if (route.forward(from, at) < stretch)
			{
				Path2D head = arrowhead(view, onRoute(route, at, length), length, ARROW_HALF_WIDTH, ARROW_NOTCH);
				if (head != null)
				{
					graphics.fill(head);
				}
			}
		}
	}

	/**
	 * Marks where each shoal is on its route with an arrow pointing the way it's heading.
	 */
	private void drawShoalArrows(Graphics2D graphics, List<PlacedShoal> shoals, long now)
	{
		if (!config.showShoalHeadingArrow())
		{
			return;
		}

		Color colour = config.shoalHeadingArrowColour();
		double length = shoalArrowLength();
		for (PlacedShoal placed : shoals)
		{
			// Fades out while the shoal sits at a stop, and back in as it's about to set off again.
			double opacity = placed.headingOpacity;
			if (opacity <= 0)
			{
				continue;
			}

			// Snap the arrow onto the route, so it slides along the line with the shoal.
			Path2D arrow = arrowhead(placed.view, onRoute(placed.route, placed.distance, length), length, SHOAL_ARROW_HALF_WIDTH, SHOAL_ARROW_NOTCH);
			if (arrow != null)
			{
				graphics.setColor(withOpacity(colour, opacity));
				graphics.fill(arrow);
			}
		}
	}

	/**
	 * Where an arrow of the given length in tiles sits on a route, as {x, y, dx, dy}: aimed from the route
	 * half its length behind to the route half its length ahead, and centred between the two. On a bend
	 * that puts both its tip and its tail on the line, where following the direction at its middle sends
	 * the tip off the outside of the bend.
	 */
	private static double[] onRoute(ShoalRoute route, double distance, double length)
	{
		double[] behind = route.pointAt(distance - length / 2);
		double[] ahead = route.pointAt(distance + length / 2);
		double dx = ahead[0] - behind[0];
		double dy = ahead[1] - behind[1];
		double across = Math.hypot(dx, dy);
		if (across < 1e-9)
		{
			return route.pointAt(distance);
		}
		return new double[]{(behind[0] + ahead[0]) / 2, (behind[1] + ahead[1]) / 2, dx / across, dy / across};
	}

	/**
	 * An arrowhead lying flat on the water, centred on a point of a route and pointing along it, or
	 * null if any of it can't be drawn. The point is {x, y, dx, dy}, as ShoalRoute.pointAt gives it.
	 * The length is in tiles; the half width and notch are fractions of it.
	 */
	private Path2D arrowhead(WorldView view, double[] at, double length, double halfWidthFraction, double notchFraction)
	{
		double halfLength = length / 2;
		double halfWidth = length * halfWidthFraction;
		double notch = length * notchFraction;
		double x = at[0];
		double y = at[1];
		double dx = at[2];
		double dy = at[3];
		Point tip = toCanvas(view, x + dx * halfLength, y + dy * halfLength);
		Point left = toCanvas(view, x - dx * halfLength - dy * halfWidth, y - dy * halfLength + dx * halfWidth);
		Point back = toCanvas(view, x - dx * notch, y - dy * notch);
		Point right = toCanvas(view, x - dx * halfLength + dy * halfWidth, y - dy * halfLength - dx * halfWidth);
		if (tip == null || left == null || back == null || right == null)
		{
			return null;
		}

		Path2D.Double arrow = new Path2D.Double();
		arrow.moveTo(tip.getX(), tip.getY());
		arrow.lineTo(left.getX(), left.getY());
		arrow.lineTo(back.getX(), back.getY());
		arrow.lineTo(right.getX(), right.getY());
		arrow.closePath();
		return arrow;
	}

	private void drawStop(Graphics2D graphics, WorldView view, ShoalRoute route, int stop, Color colour, double opacity)
	{
		LocalPoint local = toLocal(view, route.stopX(stop), route.stopY(stop));
		Polygon area = local == null ? null : Perspective.getCanvasTileAreaPoly(client, local, STOP_SIZE);
		if (area != null)
		{
			OverlayUtil.renderPolygon(graphics, area, withOpacity(colour, opacity), withOpacity(STOP_FILL, opacity),
				new BasicStroke(config.stopThickness().pixels()));
		}
	}

	/**
	 * A colour with its own transparency scaled by an opacity from 0 to 1.
	 */
	private static Color withOpacity(Color colour, double opacity)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), (int) Math.round(colour.getAlpha() * opacity));
	}

	/**
	 * A colour part way from one to another, by a fraction from 0 to 1.
	 */
	private static Color blend(Color from, Color to, double fraction)
	{
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * fraction),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * fraction),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * fraction));
	}

	/**
	 * The length of the shoal heading arrow, and of the arrow leading an animated section, in tiles.
	 */
	private double shoalArrowLength()
	{
		return scaled(SHOAL_ARROW_LENGTH, config.shoalHeadingArrowScale());
	}

	/**
	 * Outlines the water the nearest shoal can be fished from, as a square or circle around the shoal,
	 * and says whether it drew it. The shape is centred on the shoal itself, so it travels with the shoal
	 * and only sits still because the shoal does.
	 */
	private boolean drawFishableArea(Graphics2D graphics)
	{
		Shoal shoal = plugin.getNearestShoal();
		WorldView view = shoal == null ? null : shoal.parentView(client);
		double[] at = shoal == null ? null : shoal.position(client);
		if (view == null || at == null)
		{
			return false;
		}

		// Walked around the shape a point at a time, so one running off the loaded map still draws the
		// part that is on it. The same shape every frame, so it is drawn into the same polygon rather
		// than a new one, off points worked out once.
		boolean circle = config.fishableAreaShape() == TrawlingPlusConfig.FishableShape.CIRCLE;
		double[] shapeX = circle ? CIRCLE_X : SQUARE_X;
		double[] shapeY = circle ? CIRCLE_Y : SQUARE_Y;
		area.reset();
		for (int step = 0; step < AREA_POINTS; step++)
		{
			Point edge = toCanvas(view, at[0] + shapeX[step] * FISHABLE_REACH, at[1] + shapeY[step] * FISHABLE_REACH);
			if (edge != null)
			{
				area.addPoint(edge.getX(), edge.getY());
			}
		}

		if (area.npoints < AREA_POINTS / 4)
		{
			// Too little of it is on screen to make a shape out of.
			return false;
		}

		OverlayUtil.renderPolygon(graphics, area, config.fishableAreaColour(),
			config.fishableAreaFillColour(), areaOutline(config.fishableAreaThickness().pixels()));
		return true;
	}

	/**
	 * A dot on the boat at the point the fishable area is measured to, so the boat can fish the shoal
	 * whenever the dot is inside it. It fades in as the area appears and out as it goes.
	 */
	private void drawFishingPoint(Graphics2D graphics, boolean wanted, long now)
	{
		// Not drawn for a while, as when off the boat, so it starts from nothing rather than jumping in.
		if (lastFishingPointMillis < 0 || now - lastFishingPointMillis > FISHING_POINT_FADE_MILLIS * 2)
		{
			fishingPointFade = 0;
			lastFishingPointMillis = now;
		}
		double step = (now - lastFishingPointMillis) / FISHING_POINT_FADE_MILLIS;
		lastFishingPointMillis = now;
		fishingPointFade = wanted ? Math.min(1, fishingPointFade + step) : Math.max(0, fishingPointFade - step);
		if (fishingPointFade <= 0)
		{
			return;
		}

		WorldEntity boat = plugin.getBoat();
		WorldView deck = boat == null ? null : boat.getWorldView();
		WorldEntityConfig hull = boat == null ? null : boat.getConfig();
		if (deck == null || hull == null)
		{
			return;
		}

		// Down the middle of the boat, which on a hull an odd number of tiles wide is half a tile off the
		// middle of its view, as at the helm.
		int across = deck.getSizeX() * Perspective.LOCAL_TILE_SIZE / 2;
		if ((hull.getBoundsWidth() / Perspective.LOCAL_TILE_SIZE) % 2 != 0)
		{
			across -= Perspective.LOCAL_HALF_TILE_SIZE;
		}
		LocalPoint afloat = boat.transformToMainWorld(new LocalPoint(across,
			deck.getSizeY() * Perspective.LOCAL_TILE_SIZE / 2 - FISHING_POINT_AHEAD, deck));
		WorldView sea = afloat == null ? null : client.getWorldView(afloat.getWorldView());
		if (sea == null)
		{
			return;
		}

		// At the water's height, the same as the area it is read against.
		int height = sea.getTileHeight(afloat.getX(), afloat.getY(), sea.getPlane());
		Point point = Perspective.localToCanvas(client, afloat.getWorldView(), afloat.getX(), afloat.getY(), height);
		if (point == null)
		{
			return;
		}

		graphics.setColor(withOpacity(TrawlingPlusNetOverlay.opaque(config.fishableAreaColour()), fishingPointFade));
		graphics.fillOval(point.getX() - FISHING_POINT_SIZE / 2, point.getY() - FISHING_POINT_SIZE / 2,
			FISHING_POINT_SIZE, FISHING_POINT_SIZE);
	}

	private Stroke areaOutline(int pixels)
	{
		if (areaStroke == null || pixels != areaThickness)
		{
			areaThickness = pixels;
			areaStroke = new BasicStroke(pixels);
		}
		return areaStroke;
	}

	/**
	 * An arrow's length in tiles, from its length at 100% and an arrow scaling setting.
	 */
	private static double scaled(double length, int percent)
	{
		return length * Math.max(TrawlingPlusConfig.MIN_ARROW_SCALE, Math.min(TrawlingPlusConfig.MAX_ARROW_SCALE, percent)) / 100;
	}

	private Point toCanvas(WorldView view, double x, double y)
	{
		LocalPoint local = toLocal(view, x, y);
		if (local == null)
		{
			return null;
		}

		// The world view's own height lookup reaches into the extra map loaded around the scene; the one
		// Perspective.localToCanvas(client, local, plane) uses stops at the scene's edge and gives 0 beyond it.
		int height = view.getTileHeight(local.getX(), local.getY(), view.getPlane());
		return Perspective.localToCanvas(client, view.getId(), local.getX(), local.getY(), height);
	}

	/**
	 * Converts world tile coordinates to a local point, or null if they're outside the loaded map.
	 */
	private LocalPoint toLocal(WorldView view, double x, double y)
	{
		int localX = (int) Math.round((x - view.getBaseX()) * Perspective.LOCAL_TILE_SIZE) + Perspective.LOCAL_HALF_TILE_SIZE;
		int localY = (int) Math.round((y - view.getBaseY()) * Perspective.LOCAL_TILE_SIZE) + Perspective.LOCAL_HALF_TILE_SIZE;
		int beyond = tilesBeyondScene(view) * Perspective.LOCAL_TILE_SIZE;
		if (localX < -beyond || localY < -beyond
			|| localX >= view.getSizeX() * Perspective.LOCAL_TILE_SIZE + beyond
			|| localY >= view.getSizeY() * Perspective.LOCAL_TILE_SIZE + beyond)
		{
			return null;
		}
		return new LocalPoint(localX, localY, view);
	}

	/**
	 * How many tiles of map are loaded beyond each edge of a world view's scene. The GPU and 117 HD
	 * plugins' extended map loading adds whole chunks around the top-level scene, up to the extended
	 * scene's size; other world views have none.
	 */
	private int tilesBeyondScene(WorldView view)
	{
		if (!view.isTopLevel())
		{
			return 0;
		}
		int most = (Constants.EXTENDED_SCENE_SIZE - Constants.SCENE_SIZE) / 2;
		return Math.max(0, Math.min(most, client.getExpandedMapLoading() * Constants.CHUNK_SIZE));
	}

	/**
	 * A shoal matched to a route, with where it is this frame, how far round its route that is, and the
	 * stop it's heading for. Placing a shoal searches its whole route, so it's done once per frame.
	 */
	private static final class PlacedShoal
	{
		final Shoal shoal;
		final ShoalRoute route;
		final WorldView view;
		final double distance;
		final int next;
		// How far faded in the heading arrow is this frame, which the stop just reached fades out with.
		final double headingOpacity;

		PlacedShoal(Shoal shoal, ShoalRoute route, WorldView view, double[] position, long now)
		{
			this.shoal = shoal;
			this.route = route;
			this.view = view;
			distance = shoal.followRoute(position);
			next = route.nextStop(distance);
			headingOpacity = shoal.headingArrowOpacity(now);
		}
	}

	/**
	 * A line built point by point on the canvas. A point that can't be drawn breaks the line, and
	 * the next one that can starts a new stretch.
	 */
	private static final class Line
	{
		private final Path2D.Double path = new Path2D.Double();
		private boolean connected;

		void add(Point point)
		{
			if (point == null)
			{
				connected = false;
			}
			else if (connected)
			{
				path.lineTo(point.getX(), point.getY());
			}
			else
			{
				path.moveTo(point.getX(), point.getY());
				connected = true;
			}
		}
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import net.runelite.api.Client;
import net.runelite.api.Point;

/**
 * Draws routes onto a map, wherever that map happens to be and at whatever scale it is drawn. Shared
 * by the minimap and the world map, which work out where a tile lands in entirely different ways.
 */
final class MapRoutes
{
	// The shape of an arrowhead on a map: half its width, and how far its back edge is notched in, as
	// fractions of its length. The length is given in pixels rather than tiles, since a map is drawn at
	// whatever scale it likes and an arrow has to stay big enough to make out without swamping the line.
	private static final double ARROW_HALF_WIDTH = 0.4;
	private static final double ARROW_NOTCH = 0.25;

	// No two arrows closer together than this on screen. Arrows sit a fixed number of tiles apart, so
	// without this they would pile into each other as a map is zoomed out. How many to leave out is
	// worked out from how far the map is zoomed, never from which of them happen to be on screen: a
	// thinning that depends on what is visible rearranges itself every time the map is panned.
	private static final int ARROW_GAP = 24;

	// How far along the route to look to see which way an arrow points, in tiles.
	private static final double ARROW_AIM = 2;

	// About how far apart the points of the drawn line should be on screen, in pixels. Closer than this
	// and they land on top of each other; further apart and a bend starts to show as a cut corner.
	private static final double LINE_STEP = 2;

	private MapRoutes()
	{
	}

	/**
	 * Turns world tile coordinates into a place on whichever map is being drawn, or null when they
	 * fall outside it.
	 */
	interface Projection
	{
		Point at(double x, double y);
	}

	/**
	 * One route as a line, broken wherever it leaves the map.
	 */
	static void route(Graphics2D graphics, TrawlingPlusConfig config, ShoalRoute route, Projection onto,
		int thickness, double pixelsPerTile, double fromX, double fromY, double toX, double toY)
	{
		// Every so many of the route's points, chosen from how far the map is zoomed. A fixed number of
		// them cuts the corners once the map is zoomed in far enough to see it, and wastes the work of
		// placing points on top of each other once it is zoomed out.
		int stride = 1;
		if (pixelsPerTile > 0 && route.sampleCount() > 0)
		{
			double apart = route.length() / route.sampleCount();
			stride = Math.max(1, (int) (LINE_STEP / (pixelsPerTile * apart)));
		}

		Path2D line = new Path2D.Double();
		boolean drawing = false;
		for (int block = 0; block < route.blockCount(); block++)
		{
			// Only the runs of the route that reach what is being shown. Most of a route is somewhere
			// else entirely, and a run is dismissed in four comparisons rather than by placing all the
			// points inside it and throwing them away one at a time.
			if (!route.blockWithin(block, fromX, fromY, toX, toY))
			{
				drawing = false;
				continue;
			}

			int start = route.blockFrom(block);
			for (int sample = start + (stride - start % stride) % stride; sample < route.blockTo(block);
				sample += stride)
			{
				Point at = onto.at(route.sampleX(sample), route.sampleY(sample));
				if (at == null)
				{
					// Off the map, so the line picks up again where it comes back.
					drawing = false;
					continue;
				}

				if (drawing)
				{
					line.lineTo(at.getX(), at.getY());
				}
				else
				{
					line.moveTo(at.getX(), at.getY());
					drawing = true;
				}
			}
		}

		graphics.setColor(config.routeColour());
		graphics.setStroke(new BasicStroke(thickness));
		graphics.draw(line);
	}

	/**
	 * The stretches of a route that pass close to where sea creatures that attack boats spawn, drawn over its
	 * line in the given colour and broken wherever the route is safe or leaves the map.
	 */
	static void dangerStretches(Graphics2D graphics, ShoalRoute route, Projection onto, Color colour, int thickness,
		double pixelsPerTile, double fromX, double fromY, double toX, double toY)
	{
		// The same thinning of points as the route line itself, so the two lie on top of each other.
		int stride = 1;
		if (pixelsPerTile > 0 && route.sampleCount() > 0)
		{
			double apart = route.length() / route.sampleCount();
			stride = Math.max(1, (int) (LINE_STEP / (pixelsPerTile * apart)));
		}

		Path2D line = new Path2D.Double();
		boolean drawing = false;
		for (int block = 0; block < route.blockCount(); block++)
		{
			if (!route.blockWithin(block, fromX, fromY, toX, toY))
			{
				drawing = false;
				continue;
			}

			int start = route.blockFrom(block);
			for (int sample = start + (stride - start % stride) % stride; sample < route.blockTo(block);
				sample += stride)
			{
				Point at = route.dangerAt(sample) ? onto.at(route.sampleX(sample), route.sampleY(sample)) : null;
				if (at == null)
				{
					drawing = false;
					continue;
				}

				if (drawing)
				{
					line.lineTo(at.getX(), at.getY());
				}
				else
				{
					line.moveTo(at.getX(), at.getY());
					drawing = true;
				}
			}
		}

		graphics.setColor(colour);
		graphics.setStroke(new BasicStroke(thickness));
		graphics.draw(line);
	}

	/**
	 * The arrows showing which way round a route is swum, at the spacing set for the ones on the water
	 * but thinned out so they never crowd each other on a map drawn small. Those on a stretch marked
	 * dangerous take the danger colour instead, when one is given.
	 */
	static void arrows(Graphics2D graphics, TrawlingPlusConfig config, ShoalRoute route, Projection onto,
		int size, double pixelsPerTile, double fromX, double fromY, double toX, double toY, Color dangerColour)
	{
		if (!config.showDirectionArrows())
		{
			return;
		}

		int spacing = Math.max(TrawlingPlusConfig.MIN_ARROW_SPACING,
			Math.min(TrawlingPlusConfig.MAX_ARROW_SPACING, config.directionArrowSpacing()));

		// Every so many of the arrows, chosen so that what is left of them is far enough apart on screen.
		// They then sit at fixed places round the route and stay put however the map is moved about.
		int every = 1;
		if (pixelsPerTile > 0)
		{
			every = Math.max(1, (int) Math.ceil(ARROW_GAP / pixelsPerTile / spacing));
		}

		double apart = (double) every * spacing;
		Color arrowColour = config.directionArrowColour();
		for (int block = 0; block < route.blockCount(); block++)
		{
			// The same skipping the line is drawn with. A run of the route covers one stretch of the way
			// round it, so the arrows on it are the ones whose distances fall inside that stretch, and the
			// rest are passed over without ever being worked out.
			if (!route.blockWithin(block, fromX, fromY, toX, toY))
			{
				continue;
			}

			double opens = route.sampleDistance(route.blockFrom(block));
			double closes = route.blockTo(block) < route.sampleCount()
				? route.sampleDistance(route.blockTo(block)) : route.length();

			for (int arrow = Math.max(1, (int) Math.ceil(opens / apart)); arrow * apart < closes; arrow++)
			{
				double[] point = route.pointAt(arrow * apart);
				if (point[0] < fromX || point[0] > toX || point[1] < fromY || point[1] > toY)
				{
					// Inside a run that reaches the map, but not itself on the part of it being shown.
					continue;
				}

				Point at = onto.at(point[0], point[1]);
				if (at == null)
				{
					continue;
				}

				// Which way the arrow points is read from a second place further along the route. That one
				// can be off the map while the arrow itself is on it, which happens along the edge once the
				// map is zoomed in far enough for a couple of tiles to be a long way across the screen, so
				// the place behind the arrow is taken instead and the direction turned around.
				Point ahead = onto.at(point[0] + point[2] * ARROW_AIM, point[1] + point[3] * ARROW_AIM);
				Point from = ahead != null ? at
					: onto.at(point[0] - point[2] * ARROW_AIM, point[1] - point[3] * ARROW_AIM);
				Point to = ahead != null ? ahead : at;
				if (from == null || to == null || (to.getX() == from.getX() && to.getY() == from.getY()))
				{
					// Neither way along the route could be placed, or both ends landed on the same pixel and
					// there is no direction to read from them.
					continue;
				}

				// An arrow on a stretch drawn red is red too, so it doesn't break the stretch up.
				graphics.setColor(dangerColour != null && route.dangerAtDistance(arrow * apart) ? dangerColour : arrowColour);
				graphics.fill(
					arrowhead(at, Math.atan2(to.getY() - from.getY(), to.getX() - from.getX()), size));
			}
		}
	}

	/**
	 * Where a shoal is right now, as a dot in the colour that marks it on the water.
	 */
	static void shoal(Graphics2D graphics, TrawlingPlusConfig config, Client client, Shoal shoal,
		Projection onto, int size)
	{
		double[] swimming = shoal.position(client);
		Point at = swimming == null ? null : onto.at(swimming[0], swimming[1]);
		if (at == null)
		{
			return;
		}

		graphics.setColor(config.shoalHeadingArrowColour());
		graphics.fillOval(at.getX() - size, at.getY() - size, size * 2, size * 2);
		// Outlined, so it stays visible whatever the map underneath it is coloured.
		graphics.setColor(Color.BLACK);
		graphics.setStroke(new BasicStroke(1));
		graphics.drawOval(at.getX() - size, at.getY() - size, size * 2, size * 2);
	}

	/**
	 * An arrowhead of the given length in pixels, centred on a point and pointing along an angle.
	 */
	private static Path2D arrowhead(Point at, double angle, int length)
	{
		double sin = Math.sin(angle);
		double cos = Math.cos(angle);
		double half = length * ARROW_HALF_WIDTH;
		double notch = length * ARROW_NOTCH;

		// Along the arrow, then across it, for the tip, both barbs and the notch between them.
		double[][] corners = {{length / 2.0, 0}, {-length / 2.0, half}, {-length / 2.0 + notch, 0},
			{-length / 2.0, -half}};
		Path2D head = new Path2D.Double();
		for (int corner = 0; corner < corners.length; corner++)
		{
			double x = at.getX() + corners[corner][0] * cos - corners[corner][1] * sin;
			double y = at.getY() + corners[corner][0] * sin + corners[corner][1] * cos;
			if (corner == 0)
			{
				head.moveTo(x, y);
			}
			else
			{
				head.lineTo(x, y);
			}
		}
		head.closePath();
		return head;
	}
}
